insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-SSMA', 'SSMA e Gestão (Transversal)', 'Todas as fases e frentes específicas (altura, confinado, quente, escavação, inflamáveis)', 'Referenciar sempre APR/PT/DDS vigentes no cabeçalho. Em NC de gravidade Crítica (risco grave e iminente), registrar a paralisação imediata da atividade e a comunicação à liderança de SSMA. NC ambiental: anexar comunicação à equipe ambiental quando houver condicionante de licença envolvida.')
insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-INFRA', 'Infraestrutura (terraplenagem, escavações, fundações, drenagem, vias)', 'Infraestrutura', 'Anexar resultados de ensaios de campo/laboratório (compactação, concreto) e levantamentos topográficos que evidenciem o desvio. Sempre citar nº/rev. do projeto executivo e, quando houver, a disposição do projetista.')
insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-ESTR', 'Estruturas (concreto, metálicas, lajes/formas/escoramento)', 'Estruturas', 'Vincular rastreabilidade de materiais (lotes de concreto/aço, certificados) e resultados de controle tecnológico. NC estrutural com peça já concretada/carregada exige disposição formal do projetista antes do fechamento.')
insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-MONT', 'Montagem Eletromecânica (trackers, módulos, içamento, solda, mecânica, pintura, torres, cabos LT)', 'Montagem', 'Citar manual do fabricante (documento e revisão) e mapa de torque quando aplicável. Danos com potencial impacto em garantia: registrar comunicação formal ao fabricante/fornecedor. Solda: anexar relatórios de END quando executados.')
insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-ELETRO', 'Eletromontagem (cabos, MT, conexões, aterramento, painéis, SE primária, iluminação)', 'Eletromontagem', 'NC em instalações energizáveis: registrar estado da instalação (desenergizada/impedida) e requisitos NR-10 no fechamento. Anexar resultados de ensaios (megger, resistência de aterramento, VLF) que fundamentem a correção.')
insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-COMIS', 'Comissionamento (walkdown, testes a frio/quente, SAS, energização, TAC/TAF)', 'Pré-comissionamento, Comissionamento e Entrega', 'Vincular a NC ao plano de teste (documento/revisão) e à punch list (categoria A/B/C). NC impeditiva de energização deve ser sinalizada como bloqueio formal. Requisitos ONS/concessionária: citar submódulo/procedimento aplicável.')
insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-EDIF', 'Edificações — Execução (vedações, instalações, acabamentos, cobertura, fachada)', 'Vedações, Instalações, Acabamentos, Cobertura e Fachada', 'Referenciar o memorial descritivo e a NBR 15575 (desempenho) quando o desvio afetar requisitos de desempenho. Fachada e serviços em altura: NC de sistema de acesso/proteção segue tratamento de gravidade Crítica com paralisação.')
insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-ENTREGA', 'Entrega e Finalização (vistoria de unidades, cercamento, CFTV, aceitação telecom)', 'Entrega e Finalização', 'Consolidar pendências em punch list/termo de vistoria com prazos. A aceitação (TAC/TAF/termo de entrega) deve ficar condicionada ao fechamento das NCs impeditivas e à entrega documental (as-built, laudos, manuais).')
insert into public.rnc_modelos (id, nome, fases_contextos, particularidades) values ('RNC-REF', 'Reformas (planejamento, demolição, execução e entrega)', 'Etapa inicial e etapas gerais', 'Citar o plano de reforma aprovado (NBR 16280) com ART/RRT no cabeçalho. NC de escopo não aprovado ou interferência estrutural: gravidade mínima Maior, com comunicação ao responsável legal da edificação.')
