insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (1, 'Identificação do Relatório', 'Nº da RNC ({{numero_rnc}}), obra/empreendimento ({{obra}}), cliente ({{cliente}}), contratada inspecionada ({{contratada}}), data da inspeção ({{data_inspecao}}) e inspetor responsável ({{inspetor}}).', 'Automático (plataforma)', false)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (2, 'Origem da Inspeção', 'Checklist de origem ({{checklist_codigo}} – {{checklist_nome}}), item verificado nº {{item_numero}} ({{item_verificacao}}), fase/contexto e, quando aplicável, projeto executivo de referência nº {{projeto_num}} rev. {{projeto_rev}}.', 'Automático (plataforma)', false)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (3, 'Local e Ativo Inspecionado', 'Localização precisa da NC ({{local}}) e identificação do ativo/elemento ({{ativo}}) — ex.: eixo/fileira, estrutura, circuito, pavimento, unidade.', 'Inspetor (campo)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (4, 'Descrição da Não Conformidade', 'Relato objetivo e factual da condição encontrada ({{descricao_nc}}), sem juízo de valor — o que foi visto, medido ou constatado.', 'Inspetor (campo)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (5, 'Evidência Fotográfica', 'Fotos anotadas ({{evidencia_foto}}) com legenda, data e localização. Mínimo recomendado: 1 foto panorâmica (contexto) + 1 foto de detalhe.', 'Inspetor (campo)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (6, 'Requisito Descumprido', 'TEXTO-BASE (aba TEXTOS_BASE, coluna "Requisito Descumprido"): parágrafo pré-redigido vinculando o fato ao item e critério do checklist. Preenchido pelo agente de IA; editável pelo cliente.', 'Agente de IA (texto-base)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (7, 'Fundamentação Normativa', 'TEXTO-BASE (coluna "Fundamentação Normativa"): citação da norma/NR/manual de referência e do requisito aplicável, dando lastro técnico-legal ao apontamento.', 'Agente de IA (texto-base)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (8, 'Classificação de Gravidade', 'Crítica / Maior / Menor / Observação ({{gravidade}}), coerente com a classificação de segurança (pirâmide de Bird) da plataforma. Partir da sugestão da coluna "Gravidade sugerida" e ajustar ao caso concreto.', 'Agente de IA (sugestão) + Inspetor (decisão)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (9, 'Análise de Risco / Consequência Potencial', 'TEXTO-BASE (coluna "Risco/Consequência"): consequências típicas da condição para pessoas, ativos, meio ambiente, prazo e contrato, complementável pelo inspetor ({{risco_complementar}}).', 'Agente de IA (texto-base)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (10, 'Ação Corretiva Requerida', 'TEXTO-BASE (coluna "Ação Corretiva"): correção imediata + ação sistêmica + evidência de fechamento, com prazo ({{prazo}}) e responsável ({{responsavel}}).', 'Agente de IA (texto-base)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (11, 'Disposição e Acompanhamento', 'Status ({{status}}: Aberta / Em tratamento / Aguardando reinspeção / Fechada / Cancelada), datas e histórico de tratativas.', 'Plataforma (workflow de NC)', true)
insert into public.rnc_secoes (ordem, secao, conteudo_instrucao, origem_dado, editavel) values (12, 'Fechamento e Assinaturas', 'Resultado da reinspeção ({{reinspecao_resultado}}), evidência da correção ({{evidencia_foto_correcao}}), data de fechamento ({{data_fechamento}}) e assinaturas (inspetor e responsável da contratada).', 'Inspetor + Contratada', true)
