insert into public.rnc_placeholders (placeholder, significado, origem_dado, obrigatorio) values ('{{data_fechamento}}', 'Data de fechamento da RNC', 'Plataforma (workflow)', 'Para fechamento')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "APR disponível na frente de serviço" (item 1 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: APR impressa/digital acessível no local da atividade. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "APR impressa/digital acessível no local da atividade" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "APR impressa/digital acessível no local da atividade"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "APR assinada por todos os executantes" (item 2 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: Assinaturas de toda a equipe e do responsável. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "Assinaturas de toda a equipe e do responsável" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Assinaturas de toda a equipe e do responsável"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 3, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "APR compatível com a atividade real" (item 3 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: Riscos e etapas descritos correspondem ao que está sendo executado. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "Riscos e etapas descritos correspondem ao que está sendo executado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Riscos e etapas descritos correspondem ao que está sendo executado"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 4, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "DDS realizado e registrado" (item 4 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: Registro diário com tema, lista de presença e assinaturas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "Registro diário com tema, lista de presença e assinaturas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Registro diário com tema, lista de presença e assinaturas"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 5, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Permissão de Trabalho (PT) emitida" (item 5 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: PT válida para atividades especiais (altura, quente, elétrica, confinado). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "PT válida para atividades especiais (altura, quente, elétrica, confinado)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "PT válida para atividades especiais (altura, quente, elétrica, confinado)"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 6, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Equipe treinada para a atividade" (item 6 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: Certificados válidos das NRs aplicáveis. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "Certificados válidos das NRs aplicáveis" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Certificados válidos das NRs aplicáveis"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
