insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 10, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Medidas de controle implantadas" (item 10 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: Hierarquia de controles aplicada (eliminação → EPI). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "Hierarquia de controles aplicada (eliminação → EPI)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Hierarquia de controles aplicada (eliminação → EPI)"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 11, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Mudanças na atividade reavaliadas" (item 11 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: Alteração de escopo gerou revisão da APR/PT. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "Alteração de escopo gerou revisão da APR/PT" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Alteração de escopo gerou revisão da APR/PT"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-01', 12, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "PGR do canteiro atualizado" (item 12 do checklist ST-01 – Gerenciamento de Riscos (GRO/PGR)). Critério de aceitação aplicável: Inventário de riscos e plano de ação vigentes. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 (Disposições Gerais e Gerenciamento de Riscos Ocupacionais) estabelece a obrigatoriedade do GRO e do PGR, exigindo inventário de riscos atualizado, plano de ação vigente e ferramentas de gestão de risco na frente de serviço (APR, PT, DDS) coerentes com as atividades reais executadas. Referência-base aplicável: NR-01 – Gerenciamento de Riscos (GRO/PGR) · documento/manual do cliente quando aplicável. O critério "Inventário de riscos e plano de ação vigentes" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'A ausência ou inadequação das ferramentas de gestão de riscos expõe trabalhadores a perigos não identificados e não controlados, elevando a probabilidade de acidentes com lesão e caracterizando descumprimento legal passível de embargo, interdição e autuação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Inventário de riscos e plano de ação vigentes"; (ii) revisar/emitir a documentação de gestão de riscos aplicável (APR/PT/PGR), realinhar a equipe via DDS extraordinário e garantir aderência entre documento e atividade executada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-02', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Capacete com jugular" (item 1 do checklist ST-02 – Equipamentos de Proteção Individual). Critério de aceitação aplicável: Uso correto, jugular ajustada em altura/içamento. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-06 (Equipamento de Proteção Individual) obriga o fornecimento gratuito de EPI adequado ao risco, com Certificado de Aprovação (CA) válido, em perfeito estado de conservação, com treinamento de uso e fiscalização de utilização pelo empregador. Referência-base aplicável: NR-06 – Equipamentos de Proteção Individual · documento/manual do cliente quando aplicável. O critério "Uso correto, jugular ajustada em altura/içamento" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'EPI ausente, inadequado, danificado ou com CA vencido deixa o trabalhador diretamente exposto ao agente de risco, podendo resultar em lesões graves; configura infração à NR-06 com responsabilização do empregador. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Uso correto, jugular ajustada em altura/içamento"; (ii) substituir/fornecer imediatamente o EPI adequado com CA válido, registrar entrega em ficha de EPI e reforçar treinamento de uso e conservação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-02', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Óculos de proteção" (item 2 do checklist ST-02 – Equipamentos de Proteção Individual). Critério de aceitação aplicável: Compatível com o risco (impacto, UV, respingo). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-06 (Equipamento de Proteção Individual) obriga o fornecimento gratuito de EPI adequado ao risco, com Certificado de Aprovação (CA) válido, em perfeito estado de conservação, com treinamento de uso e fiscalização de utilização pelo empregador. Referência-base aplicável: NR-06 – Equipamentos de Proteção Individual · documento/manual do cliente quando aplicável. O critério "Compatível com o risco (impacto, UV, respingo)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'EPI ausente, inadequado, danificado ou com CA vencido deixa o trabalhador diretamente exposto ao agente de risco, podendo resultar em lesões graves; configura infração à NR-06 com responsabilização do empregador. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Compatível com o risco (impacto, UV, respingo)"; (ii) substituir/fornecer imediatamente o EPI adequado com CA válido, registrar entrega em ficha de EPI e reforçar treinamento de uso e conservação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
