insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-02', 8, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Colete refletivo" (item 8 do checklist ST-02 – Equipamentos de Proteção Individual). Critério de aceitação aplicável: Áreas com tráfego de veículos/máquinas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-06 (Equipamento de Proteção Individual) obriga o fornecimento gratuito de EPI adequado ao risco, com Certificado de Aprovação (CA) válido, em perfeito estado de conservação, com treinamento de uso e fiscalização de utilização pelo empregador. Referência-base aplicável: NR-06 – Equipamentos de Proteção Individual · documento/manual do cliente quando aplicável. O critério "Áreas com tráfego de veículos/máquinas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'EPI ausente, inadequado, danificado ou com CA vencido deixa o trabalhador diretamente exposto ao agente de risco, podendo resultar em lesões graves; configura infração à NR-06 com responsabilização do empregador. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Áreas com tráfego de veículos/máquinas"; (ii) substituir/fornecer imediatamente o EPI adequado com CA válido, registrar entrega em ficha de EPI e reforçar treinamento de uso e conservação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-02', 9, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Proteção respiratória" (item 9 do checklist ST-02 – Equipamentos de Proteção Individual). Critério de aceitação aplicável: Máscara correta para poeira/fumos, com PPR quando aplicável. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-06 (Equipamento de Proteção Individual) obriga o fornecimento gratuito de EPI adequado ao risco, com Certificado de Aprovação (CA) válido, em perfeito estado de conservação, com treinamento de uso e fiscalização de utilização pelo empregador. Referência-base aplicável: NR-06 – Equipamentos de Proteção Individual · documento/manual do cliente quando aplicável. O critério "Máscara correta para poeira/fumos, com PPR quando aplicável" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'EPI ausente, inadequado, danificado ou com CA vencido deixa o trabalhador diretamente exposto ao agente de risco, podendo resultar em lesões graves; configura infração à NR-06 com responsabilização do empregador. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Máscara correta para poeira/fumos, com PPR quando aplicável"; (ii) substituir/fornecer imediatamente o EPI adequado com CA válido, registrar entrega em ficha de EPI e reforçar treinamento de uso e conservação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
