insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-03', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Painéis e circuitos identificados" (item 1 do checklist ST-03 – Instalações e Serviços em Eletricidade). Critério de aceitação aplicável: Identificação legível de painéis, disjuntores e circuitos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-10 (Segurança em Instalações e Serviços em Eletricidade) exige medidas de controle coletivas e individuais, desenergização com bloqueio e impedimento de reenergização, trabalhadores autorizados e qualificados, e documentação (prontuário, esquemas) compatível com a instalação. Referência-base aplicável: NR-10 – Instalações e Serviços em Eletricidade · documento/manual do cliente quando aplicável. O critério "Identificação legível de painéis, disjuntores e circuitos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'O descumprimento de requisitos da NR-10 expõe trabalhadores a choque elétrico, arco voltaico e queimaduras, com elevado potencial de fatalidade; em SEP, o risco é agravado pelos níveis de tensão e energia incidente. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Identificação legível de painéis, disjuntores e circuitos"; (ii) paralisar a atividade elétrica até restabelecer as condições seguras (desenergização/bloqueio, autorização, EPI/EPC classe compatível) e revalidar a PT; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-03', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Bloqueio e etiquetagem (LOTO)" (item 2 do checklist ST-03 – Instalações e Serviços em Eletricidade). Critério de aceitação aplicável: Cadeados individuais e etiquetas aplicados nas fontes de energia. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-10 (Segurança em Instalações e Serviços em Eletricidade) exige medidas de controle coletivas e individuais, desenergização com bloqueio e impedimento de reenergização, trabalhadores autorizados e qualificados, e documentação (prontuário, esquemas) compatível com a instalação. Referência-base aplicável: NR-10 – Instalações e Serviços em Eletricidade · documento/manual do cliente quando aplicável. O critério "Cadeados individuais e etiquetas aplicados nas fontes de energia" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'O descumprimento de requisitos da NR-10 expõe trabalhadores a choque elétrico, arco voltaico e queimaduras, com elevado potencial de fatalidade; em SEP, o risco é agravado pelos níveis de tensão e energia incidente. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Cadeados individuais e etiquetas aplicados nas fontes de energia"; (ii) paralisar a atividade elétrica até restabelecer as condições seguras (desenergização/bloqueio, autorização, EPI/EPC classe compatível) e revalidar a PT; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
