insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-04', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Plano de rigging elaborado e aprovado" (item 1 do checklist ST-04 – Movimentação de Cargas / Içamento). Critério de aceitação aplicável: Içamentos críticos com plano assinado por profissional habilitado. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-11 e o plano de rigging aprovado estabelecem requisitos para movimentação e içamento de cargas: equipamentos inspecionados e com capacidade compatível, acessórios de içamento íntegros e certificados, operadores habilitados, isolamento da área e sinaleiro designado. Referência-base aplicável: NR-11 – Movimentação de Cargas / Içamento · documento/manual do cliente quando aplicável. O critério "Içamentos críticos com plano assinado por profissional habilitado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas em içamento podem resultar em queda de carga, tombamento de equipamento e esmagamento, com potencial de fatalidade múltipla e danos materiais elevados. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Içamentos críticos com plano assinado por profissional habilitado"; (ii) suspender a movimentação até adequação (inspeção de acessórios, verificação de capacidade x carga, isolamento de área, plano de rigging revalidado); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-04', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Operador habilitado e autorizado" (item 2 do checklist ST-04 – Movimentação de Cargas / Içamento). Critério de aceitação aplicável: CNH/certificação compatível com o equipamento, ASO válido. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-11 e o plano de rigging aprovado estabelecem requisitos para movimentação e içamento de cargas: equipamentos inspecionados e com capacidade compatível, acessórios de içamento íntegros e certificados, operadores habilitados, isolamento da área e sinaleiro designado. Referência-base aplicável: NR-11 – Movimentação de Cargas / Içamento · documento/manual do cliente quando aplicável. O critério "CNH/certificação compatível com o equipamento, ASO válido" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas em içamento podem resultar em queda de carga, tombamento de equipamento e esmagamento, com potencial de fatalidade múltipla e danos materiais elevados. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "CNH/certificação compatível com o equipamento, ASO válido"; (ii) suspender a movimentação até adequação (inspeção de acessórios, verificação de capacidade x carga, isolamento de área, plano de rigging revalidado); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
