insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-04', 12, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Equipamento inspecionado" (item 12 do checklist ST-04 – Movimentação de Cargas / Içamento). Critério de aceitação aplicável: Checklist diário + inspeção/laudo periódico (guindaste, munck, MEWP). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-11 e o plano de rigging aprovado estabelecem requisitos para movimentação e içamento de cargas: equipamentos inspecionados e com capacidade compatível, acessórios de içamento íntegros e certificados, operadores habilitados, isolamento da área e sinaleiro designado. Referência-base aplicável: NR-11 – Movimentação de Cargas / Içamento · documento/manual do cliente quando aplicável. O critério "Checklist diário + inspeção/laudo periódico (guindaste, munck, MEWP)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas em içamento podem resultar em queda de carga, tombamento de equipamento e esmagamento, com potencial de fatalidade múltipla e danos materiais elevados. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Checklist diário + inspeção/laudo periódico (guindaste, munck, MEWP)"; (ii) suspender a movimentação até adequação (inspeção de acessórios, verificação de capacidade x carga, isolamento de área, plano de rigging revalidado); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-04', 13, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Patolamento e nivelamento adequados" (item 13 do checklist ST-04 – Movimentação de Cargas / Içamento). Critério de aceitação aplicável: Solo compactado, pranchas de apoio, equipamento nivelado. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-11 e o plano de rigging aprovado estabelecem requisitos para movimentação e içamento de cargas: equipamentos inspecionados e com capacidade compatível, acessórios de içamento íntegros e certificados, operadores habilitados, isolamento da área e sinaleiro designado. Referência-base aplicável: NR-11 – Movimentação de Cargas / Içamento · documento/manual do cliente quando aplicável. O critério "Solo compactado, pranchas de apoio, equipamento nivelado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas em içamento podem resultar em queda de carga, tombamento de equipamento e esmagamento, com potencial de fatalidade múltipla e danos materiais elevados. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Solo compactado, pranchas de apoio, equipamento nivelado"; (ii) suspender a movimentação até adequação (inspeção de acessórios, verificação de capacidade x carga, isolamento de área, plano de rigging revalidado); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-05', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Proteções fixas e móveis instaladas" (item 1 do checklist ST-05 – Máquinas e Equipamentos). Critério de aceitação aplicável: Partes móveis enclausuradas, intertravamentos funcionais. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-12 (Segurança no Trabalho em Máquinas e Equipamentos) exige proteções fixas e móveis funcionais, dispositivos de parada de emergência, manutenção preventiva registrada e capacitação dos operadores. Referência-base aplicável: NR-12 – Máquinas e Equipamentos · documento/manual do cliente quando aplicável. O critério "Partes móveis enclausuradas, intertravamentos funcionais" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Máquinas sem proteção ou com dispositivos de segurança neutralizados expõem operadores a prensamento, corte, amputação e projeção de partes, além de responsabilização objetiva do empregador. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Partes móveis enclausuradas, intertravamentos funcionais"; (ii) retirar o equipamento de operação até restabelecimento das proteções e dispositivos de segurança, com registro de manutenção e liberação formal; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
