insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-06', 20, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Extintores e primeiros socorros" (item 20 do checklist ST-06 – Condições de Segurança no Canteiro). Critério de aceitação aplicável: Distribuídos, sinalizados, carga válida, kit disponível. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-18 (Condições e Meio Ambiente de Trabalho na Indústria da Construção) estabelece requisitos de organização do canteiro, proteções coletivas, áreas de vivência, instalações provisórias e PGR do canteiro integrado às frentes de serviço. Referência-base aplicável: NR-18 – Condições de Segurança no Canteiro · documento/manual do cliente quando aplicável. O critério "Distribuídos, sinalizados, carga válida, kit disponível" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Condições inadequadas de canteiro geram exposição difusa a múltiplos riscos (queda, soterramento, choque, atropelamento), degradam a cultura de segurança e sujeitam a obra a embargo/interdição pela fiscalização do trabalho. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Distribuídos, sinalizados, carga válida, kit disponível"; (ii) tratar a condição no plano de ação do PGR do canteiro, com responsável e prazo definidos, e verificar recorrência em outras frentes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-06', 21, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Rotas de fuga e mapa de emergência" (item 21 do checklist ST-06 – Condições de Segurança no Canteiro). Critério de aceitação aplicável: Desobstruídas e sinalizadas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-18 (Condições e Meio Ambiente de Trabalho na Indústria da Construção) estabelece requisitos de organização do canteiro, proteções coletivas, áreas de vivência, instalações provisórias e PGR do canteiro integrado às frentes de serviço. Referência-base aplicável: NR-18 – Condições de Segurança no Canteiro · documento/manual do cliente quando aplicável. O critério "Desobstruídas e sinalizadas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Condições inadequadas de canteiro geram exposição difusa a múltiplos riscos (queda, soterramento, choque, atropelamento), degradam a cultura de segurança e sujeitam a obra a embargo/interdição pela fiscalização do trabalho. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Desobstruídas e sinalizadas"; (ii) tratar a condição no plano de ação do PGR do canteiro, com responsável e prazo definidos, e verificar recorrência em outras frentes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-07', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "PET emitida" (item 1 do checklist ST-07 – Espaços Confinados). Critério de aceitação aplicável: Permissão de Entrada e Trabalho específica, válida só para o turno. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-33 (Segurança e Saúde nos Trabalhos em Espaços Confinados) exige identificação e sinalização dos espaços confinados, PET específica, monitoramento contínuo da atmosfera, vigia dedicado e equipe capacitada com supervisor de entrada. Referência-base aplicável: NR-33 – Espaços Confinados · documento/manual do cliente quando aplicável. O critério "Permissão de Entrada e Trabalho específica, válida só para o turno" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Entrada em espaço confinado sem os controles da NR-33 é cenário de fatalidade típica (asfixia, intoxicação, explosão), frequentemente com múltiplas vítimas incluindo socorristas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Permissão de Entrada e Trabalho específica, válida só para o turno"; (ii) interromper imediatamente qualquer entrada até emissão de PET válida, monitoramento de atmosfera e posicionamento de vigia e resgate; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
