insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-07', 11, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Espaços confinados identificados" (item 11 do checklist ST-07 – Espaços Confinados). Critério de aceitação aplicável: Cadastro e sinalização ''Entrada Proibida''. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-33 (Segurança e Saúde nos Trabalhos em Espaços Confinados) exige identificação e sinalização dos espaços confinados, PET específica, monitoramento contínuo da atmosfera, vigia dedicado e equipe capacitada com supervisor de entrada. Referência-base aplicável: NR-33 – Espaços Confinados · documento/manual do cliente quando aplicável. O critério "Cadastro e sinalização ''Entrada Proibida''" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Entrada em espaço confinado sem os controles da NR-33 é cenário de fatalidade típica (asfixia, intoxicação, explosão), frequentemente com múltiplas vítimas incluindo socorristas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Cadastro e sinalização ''Entrada Proibida''"; (ii) interromper imediatamente qualquer entrada até emissão de PET válida, monitoramento de atmosfera e posicionamento de vigia e resgate; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-08', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "PT específica para altura" (item 1 do checklist ST-08 – Trabalho em Altura). Critério de aceitação aplicável: Emitida e válida, com análise de risco. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-35 (Trabalho em Altura) exige análise de risco e PT para trabalhos acima de 2 m, sistemas de proteção contra quedas (ancoragem, talabarte, trava-quedas) inspecionados, trabalhadores capacitados e aptos, e supervisão da atividade. Referência-base aplicável: NR-35 – Trabalho em Altura · documento/manual do cliente quando aplicável. O critério "Emitida e válida, com análise de risco" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Queda de altura é uma das principais causas de óbito na construção; a ausência de ancoragem adequada, EPI inspecionado ou PT torna o evento de alta probabilidade e consequência máxima. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Emitida e válida, com análise de risco"; (ii) paralisar o trabalho em altura até restabelecimento do sistema de proteção contra quedas e revalidação da PT/análise de risco; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
