insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-10', 9, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Housekeeping pós-turno" (item 9 do checklist ST-10 – Ordem, Limpeza e Arranjo Físico). Critério de aceitação aplicável: Frente entregue limpa ao fim da jornada. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 e a NR-18 exigem ordem, limpeza e arranjo físico adequados: vias de circulação desobstruídas, materiais estocados com estabilidade, resíduos segregados e remoção regular de entulho. Referência-base aplicável: Ordem, Limpeza e Arranjo Físico · documento/manual do cliente quando aplicável. O critério "Frente entregue limpa ao fim da jornada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desorganização e acúmulo de materiais geram quedas de mesmo nível, obstrução de rotas de fuga, princípios de incêndio e ineficiência operacional. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Frente entregue limpa ao fim da jornada"; (ii) executar mutirão de organização e limpeza (housekeeping) da frente, definindo rotina e responsável pela manutenção da condição; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-11', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Levantamento manual de cargas" (item 1 do checklist ST-11 – Ergonomia). Critério de aceitação aplicável: Peso e frequência adequados, uso de meios auxiliares. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-17 (Ergonomia) exige adaptação das condições de trabalho às características dos trabalhadores, incluindo levantamento manual de cargas, posturas, mobiliário, pausas e condições ambientais de conforto. Referência-base aplicável: NR-17 – Ergonomia · documento/manual do cliente quando aplicável. O critério "Peso e frequência adequados, uso de meios auxiliares" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Condições ergonômicas inadequadas geram distúrbios osteomusculares (LER/DORT), afastamentos e queda de produtividade, com passivo trabalhista associado. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Peso e frequência adequados, uso de meios auxiliares"; (ii) adequar o posto/método de trabalho (auxílio mecânico, rodízio, pausas) e registrar a melhoria na AEP/PGR; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
