insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-12', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Armazenamento adequado de combustíveis" (item 1 do checklist ST-12 – Inflamáveis e Combustíveis). Critério de aceitação aplicável: Área específica, ventilada, afastada de ignição. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-20 (Segurança e Saúde no Trabalho com Inflamáveis e Combustíveis) exige inventário e classificação das instalações, armazenamento adequado, controle de fontes de ignição, capacitação conforme classe e plano de resposta a emergências. Referência-base aplicável: NR-20 – Inflamáveis e Combustíveis · documento/manual do cliente quando aplicável. O critério "Área específica, ventilada, afastada de ignição" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Manejo inadequado de inflamáveis pode resultar em incêndio e explosão com vítimas e perda de ativos, agravado em áreas com serviços a quente ou elétricos próximos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Área específica, ventilada, afastada de ignição"; (ii) adequar armazenamento/manuseio (bacia de contenção, afastamentos, aterramento de tambores, controle de ignição) e revalidar a análise de risco da área; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ST-12', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Bacia de contenção em tanques" (item 2 do checklist ST-12 – Inflamáveis e Combustíveis). Critério de aceitação aplicável: Volume compatível, sem trincas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-20 (Segurança e Saúde no Trabalho com Inflamáveis e Combustíveis) exige inventário e classificação das instalações, armazenamento adequado, controle de fontes de ignição, capacitação conforme classe e plano de resposta a emergências. Referência-base aplicável: NR-20 – Inflamáveis e Combustíveis · documento/manual do cliente quando aplicável. O critério "Volume compatível, sem trincas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Manejo inadequado de inflamáveis pode resultar em incêndio e explosão com vítimas e perda de ativos, agravado em áreas com serviços a quente ou elétricos próximos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Volume compatível, sem trincas"; (ii) adequar armazenamento/manuseio (bacia de contenção, afastamentos, aterramento de tambores, controle de ignição) e revalidar a análise de risco da área; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
