insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-02', 1, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Ausência de derramamento de óleo" (item 1 do checklist MA-02 – Solo e Contaminação). Critério de aceitação aplicável: Sem manchas em solo ou pátios. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A legislação ambiental aplicável e as boas práticas exigem prevenção de contaminação do solo: contenção em áreas de abastecimento e oficinas, kits de mitigação disponíveis, gestão de produtos químicos e atuação imediata sobre vazamentos. Referência-base aplicável: Solo e Contaminação · documento/manual do cliente quando aplicável. O critério "Sem manchas em solo ou pátios" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Vazamentos de óleos e produtos químicos contaminam solo e podem atingir lençol freático, gerando obrigação de remediação de alto custo e responsabilização ambiental objetiva. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Sem manchas em solo ou pátios"; (ii) conter e remediar imediatamente a área afetada, registrar o evento, e implantar/repor contenções e kits de mitigação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-02', 2, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Contenção em equipamentos estáticos" (item 2 do checklist MA-02 – Solo e Contaminação). Critério de aceitação aplicável: Bandejas sob geradores, compressores, bombas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A legislação ambiental aplicável e as boas práticas exigem prevenção de contaminação do solo: contenção em áreas de abastecimento e oficinas, kits de mitigação disponíveis, gestão de produtos químicos e atuação imediata sobre vazamentos. Referência-base aplicável: Solo e Contaminação · documento/manual do cliente quando aplicável. O critério "Bandejas sob geradores, compressores, bombas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Vazamentos de óleos e produtos químicos contaminam solo e podem atingir lençol freático, gerando obrigação de remediação de alto custo e responsabilização ambiental objetiva. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Bandejas sob geradores, compressores, bombas"; (ii) conter e remediar imediatamente a área afetada, registrar o evento, e implantar/repor contenções e kits de mitigação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
