insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-02', 5, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Área de manutenção protegida" (item 5 do checklist MA-02 – Solo e Contaminação). Critério de aceitação aplicável: Piso impermeável ou lona nas trocas de óleo em campo. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A legislação ambiental aplicável e as boas práticas exigem prevenção de contaminação do solo: contenção em áreas de abastecimento e oficinas, kits de mitigação disponíveis, gestão de produtos químicos e atuação imediata sobre vazamentos. Referência-base aplicável: Solo e Contaminação · documento/manual do cliente quando aplicável. O critério "Piso impermeável ou lona nas trocas de óleo em campo" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Vazamentos de óleos e produtos químicos contaminam solo e podem atingir lençol freático, gerando obrigação de remediação de alto custo e responsabilização ambiental objetiva. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Piso impermeável ou lona nas trocas de óleo em campo"; (ii) conter e remediar imediatamente a área afetada, registrar o evento, e implantar/repor contenções e kits de mitigação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-03', 1, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Drenagem provisória funcional" (item 1 do checklist MA-03 – Recursos Hídricos e Drenagem). Critério de aceitação aplicável: Direcionamento sem carrear sedimentos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As condicionantes de licença e o projeto de drenagem provisória exigem proteção de corpos hídricos: dispositivos de contenção de sedimentos, drenagem provisória funcional, proteção de APPs e controle de processos erosivos. Referência-base aplicável: Recursos Hídricos e Drenagem · documento/manual do cliente quando aplicável. O critério "Direcionamento sem carrear sedimentos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Carreamento de sedimentos e erosão assoreiam drenagens e corpos hídricos, danificam estruturas executadas e configuram dano ambiental com autuação e obrigação de recuperação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Direcionamento sem carrear sedimentos"; (ii) implantar/recompor dispositivos de drenagem provisória e contenção de sedimentos e corrigir os processos erosivos identificados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
