insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-03', 5, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Caixas separadoras água-óleo" (item 5 do checklist MA-03 – Recursos Hídricos e Drenagem). Critério de aceitação aplicável: Limpeza e funcionamento (lavagem/abastecimento). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As condicionantes de licença e o projeto de drenagem provisória exigem proteção de corpos hídricos: dispositivos de contenção de sedimentos, drenagem provisória funcional, proteção de APPs e controle de processos erosivos. Referência-base aplicável: Recursos Hídricos e Drenagem · documento/manual do cliente quando aplicável. O critério "Limpeza e funcionamento (lavagem/abastecimento)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Carreamento de sedimentos e erosão assoreiam drenagens e corpos hídricos, danificam estruturas executadas e configuram dano ambiental com autuação e obrigação de recuperação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Limpeza e funcionamento (lavagem/abastecimento)"; (ii) implantar/recompor dispositivos de drenagem provisória e contenção de sedimentos e corrigir os processos erosivos identificados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-04', 1, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Supressão vegetal autorizada" (item 1 do checklist MA-04 – Flora, Fauna e Emissões). Critério de aceitação aplicável: Somente na área licenciada (ASV). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As condicionantes das licenças ambientais exigem proteção de flora e fauna (supressão restrita ao autorizado, afugentamento/resgate quando previsto) e controle de emissões de poeira e ruído nas frentes e vias. Referência-base aplicável: Flora, Fauna e Emissões · documento/manual do cliente quando aplicável. O critério "Somente na área licenciada (ASV)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Supressão não autorizada, danos à fauna ou emissões excessivas configuram infração ambiental, podem suspender a licença e comprometer a relação com comunidades vizinhas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Somente na área licenciada (ASV)"; (ii) cessar a atividade irregular, comunicar a equipe ambiental responsável e implantar os controles previstos (umectação, limites de supressão, resgate); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-04', 2, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Proteção de APP" (item 2 do checklist MA-04 – Flora, Fauna e Emissões). Critério de aceitação aplicável: Áreas de preservação delimitadas e respeitadas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As condicionantes das licenças ambientais exigem proteção de flora e fauna (supressão restrita ao autorizado, afugentamento/resgate quando previsto) e controle de emissões de poeira e ruído nas frentes e vias. Referência-base aplicável: Flora, Fauna e Emissões · documento/manual do cliente quando aplicável. O critério "Áreas de preservação delimitadas e respeitadas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Supressão não autorizada, danos à fauna ou emissões excessivas configuram infração ambiental, podem suspender a licença e comprometer a relação com comunidades vizinhas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Áreas de preservação delimitadas e respeitadas"; (ii) cessar a atividade irregular, comunicar a equipe ambiental responsável e implantar os controles previstos (umectação, limites de supressão, resgate); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-04', 3, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Controle de poeira" (item 3 do checklist MA-04 – Flora, Fauna e Emissões). Critério de aceitação aplicável: Umectação de vias, controle de velocidade. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As condicionantes das licenças ambientais exigem proteção de flora e fauna (supressão restrita ao autorizado, afugentamento/resgate quando previsto) e controle de emissões de poeira e ruído nas frentes e vias. Referência-base aplicável: Flora, Fauna e Emissões · documento/manual do cliente quando aplicável. O critério "Umectação de vias, controle de velocidade" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Supressão não autorizada, danos à fauna ou emissões excessivas configuram infração ambiental, podem suspender a licença e comprometer a relação com comunidades vizinhas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Umectação de vias, controle de velocidade"; (ii) cessar a atividade irregular, comunicar a equipe ambiental responsável e implantar os controles previstos (umectação, limites de supressão, resgate); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
