insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('MA-04', 7, 'Maior — elevar a Crítica em caso de dano ambiental consumado ou violação de licença', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Condicionantes da licença atendidas" (item 7 do checklist MA-04 – Flora, Fauna e Emissões). Critério de aceitação aplicável: Checklist das condicionantes ambientais em dia. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As condicionantes das licenças ambientais exigem proteção de flora e fauna (supressão restrita ao autorizado, afugentamento/resgate quando previsto) e controle de emissões de poeira e ruído nas frentes e vias. Referência-base aplicável: Flora, Fauna e Emissões · documento/manual do cliente quando aplicável. O critério "Checklist das condicionantes ambientais em dia" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Supressão não autorizada, danos à fauna ou emissões excessivas configuram infração ambiental, podem suspender a licença e comprometer a relação com comunidades vizinhas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Checklist das condicionantes ambientais em dia"; (ii) cessar a atividade irregular, comunicar a equipe ambiental responsável e implantar os controles previstos (umectação, limites de supressão, resgate); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('QA-01', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Inspeção de recebimento" (item 1 do checklist QA-01 – Materiais e Rastreabilidade). Critério de aceitação aplicável: Materiais conferidos contra pedido/especificação. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O sistema de gestão da qualidade da obra exige materiais com certificado de qualidade/laudo do fabricante, inspeção de recebimento registrada, armazenamento conforme especificação e rastreabilidade entre lote aplicado e frente de serviço. Referência-base aplicável: Materiais e Rastreabilidade · documento/manual do cliente quando aplicável. O critério "Materiais conferidos contra pedido/especificação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Materiais sem rastreabilidade ou fora de especificação comprometem a conformidade da obra, podem exigir demolição/retrabalho e invalidam garantias contratuais. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Materiais conferidos contra pedido/especificação"; (ii) segregar e identificar o material não conforme, obter/verificar certificados e registrar a disposição (aceite, reensaio, devolução) no controle da qualidade; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('QA-01', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Certificados de materiais" (item 2 do checklist QA-01 – Materiais e Rastreabilidade). Critério de aceitação aplicável: Certificados de qualidade/ensaios arquivados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O sistema de gestão da qualidade da obra exige materiais com certificado de qualidade/laudo do fabricante, inspeção de recebimento registrada, armazenamento conforme especificação e rastreabilidade entre lote aplicado e frente de serviço. Referência-base aplicável: Materiais e Rastreabilidade · documento/manual do cliente quando aplicável. O critério "Certificados de qualidade/ensaios arquivados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Materiais sem rastreabilidade ou fora de especificação comprometem a conformidade da obra, podem exigir demolição/retrabalho e invalidam garantias contratuais. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Certificados de qualidade/ensaios arquivados"; (ii) segregar e identificar o material não conforme, obter/verificar certificados e registrar a disposição (aceite, reensaio, devolução) no controle da qualidade; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
