insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('QA-01', 5, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Identificação de status" (item 5 do checklist QA-01 – Materiais e Rastreabilidade). Critério de aceitação aplicável: Aprovado / em análise / reprovado segregado. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O sistema de gestão da qualidade da obra exige materiais com certificado de qualidade/laudo do fabricante, inspeção de recebimento registrada, armazenamento conforme especificação e rastreabilidade entre lote aplicado e frente de serviço. Referência-base aplicável: Materiais e Rastreabilidade · documento/manual do cliente quando aplicável. O critério "Aprovado / em análise / reprovado segregado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Materiais sem rastreabilidade ou fora de especificação comprometem a conformidade da obra, podem exigir demolição/retrabalho e invalidam garantias contratuais. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Aprovado / em análise / reprovado segregado"; (ii) segregar e identificar o material não conforme, obter/verificar certificados e registrar a disposição (aceite, reensaio, devolução) no controle da qualidade; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('QA-02', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Projeto disponível na frente" (item 1 do checklist QA-02 – Execução e Controle). Critério de aceitação aplicável: Última revisão, ''válido para construção''. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O plano de inspeção e testes (PIT) e os procedimentos executivos exigem execução conforme projeto e especificação, registros de inspeção (RIs/FVS) preenchidos, tratamento formal de não conformidades e liberação de etapas por responsável. Referência-base aplicável: Execução e Controle · documento/manual do cliente quando aplicável. O critério "Última revisão, ''válido para construção''" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Execução sem controle e sem registros impede a comprovação da qualidade, oculta desvios que emergem em fases posteriores com custo de correção multiplicado. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Última revisão, ''válido para construção''"; (ii) regularizar os registros de inspeção da etapa, tratar os desvios via RNC e condicionar a continuidade à liberação formal; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('QA-02', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Revisão de projeto correta" (item 2 do checklist QA-02 – Execução e Controle). Critério de aceitação aplicável: Sem uso de revisões obsoletas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O plano de inspeção e testes (PIT) e os procedimentos executivos exigem execução conforme projeto e especificação, registros de inspeção (RIs/FVS) preenchidos, tratamento formal de não conformidades e liberação de etapas por responsável. Referência-base aplicável: Execução e Controle · documento/manual do cliente quando aplicável. O critério "Sem uso de revisões obsoletas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Execução sem controle e sem registros impede a comprovação da qualidade, oculta desvios que emergem em fases posteriores com custo de correção multiplicado. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Sem uso de revisões obsoletas"; (ii) regularizar os registros de inspeção da etapa, tratar os desvios via RNC e condicionar a continuidade à liberação formal; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
