insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EQ-01', 1, 'Maior — elevar a Crítica se equipamento em uso com falha de segurança', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Checklist diário pré-uso" (item 1 do checklist EQ-01 – Máquinas, Equipamentos e Ferramentas). Critério de aceitação aplicável: Preenchido pelo operador antes do turno. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-12 e os programas de manutenção exigem máquinas, equipamentos e ferramentas inspecionados (checklist pré-uso), com proteções funcionais, manutenção em dia e operadores habilitados/autorizados. Referência-base aplicável: Máquinas, Equipamentos e Ferramentas · documento/manual do cliente quando aplicável. O critério "Preenchido pelo operador antes do turno" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Equipamento sem inspeção ou com manutenção vencida apresenta falha não detectada, expondo operadores e terceiros a acidentes mecânicos e paradas não programadas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Preenchido pelo operador antes do turno"; (ii) segregar o equipamento reprovado com etiqueta de impedimento até manutenção e reinspeção documentadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EQ-01', 2, 'Maior — elevar a Crítica se equipamento em uso com falha de segurança', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Lubrificação em dia" (item 2 do checklist EQ-01 – Máquinas, Equipamentos e Ferramentas). Critério de aceitação aplicável: Plano de lubrificação seguido. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-12 e os programas de manutenção exigem máquinas, equipamentos e ferramentas inspecionados (checklist pré-uso), com proteções funcionais, manutenção em dia e operadores habilitados/autorizados. Referência-base aplicável: Máquinas, Equipamentos e Ferramentas · documento/manual do cliente quando aplicável. O critério "Plano de lubrificação seguido" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Equipamento sem inspeção ou com manutenção vencida apresenta falha não detectada, expondo operadores e terceiros a acidentes mecânicos e paradas não programadas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Plano de lubrificação seguido"; (ii) segregar o equipamento reprovado com etiqueta de impedimento até manutenção e reinspeção documentadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
