insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('DC-01', 1, 'Menor — elevar a Maior se impedir atividade, liberação de etapa ou aceitação', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "ASO válido de todo o efetivo" (item 1 do checklist DC-01 – Documentação Legal e de SSMA). Critério de aceitação aplicável: Admissional/periódico dentro da validade. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NRs aplicáveis (NR-01, NR-07, NR-10, NR-33, NR-35, entre outras) exigem documentação legal vigente na obra: PGR, PCMSO, ASOs, certificados de treinamento, autorizações formais e ARTs dos responsáveis técnicos. Referência-base aplicável: Documentação Legal e de SSMA · documento/manual do cliente quando aplicável. O critério "Admissional/periódico dentro da validade" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Documentação ausente ou vencida caracteriza trabalhadores não aptos/não autorizados em atividade, infração administrativa e nulidade de defesas em eventual acidente. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Admissional/periódico dentro da validade"; (ii) regularizar os documentos pendentes e bloquear atividades de trabalhadores sem aptidão/autorização vigente até a regularização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('DC-01', 2, 'Menor — elevar a Maior se impedir atividade, liberação de etapa ou aceitação', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Certificados de treinamento" (item 2 do checklist DC-01 – Documentação Legal e de SSMA). Critério de aceitação aplicável: NR-10, NR-33, NR-35, NR-12, NR-18, NR-20 conforme função. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NRs aplicáveis (NR-01, NR-07, NR-10, NR-33, NR-35, entre outras) exigem documentação legal vigente na obra: PGR, PCMSO, ASOs, certificados de treinamento, autorizações formais e ARTs dos responsáveis técnicos. Referência-base aplicável: Documentação Legal e de SSMA · documento/manual do cliente quando aplicável. O critério "NR-10, NR-33, NR-35, NR-12, NR-18, NR-20 conforme função" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Documentação ausente ou vencida caracteriza trabalhadores não aptos/não autorizados em atividade, infração administrativa e nulidade de defesas em eventual acidente. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "NR-10, NR-33, NR-35, NR-12, NR-18, NR-20 conforme função"; (ii) regularizar os documentos pendentes e bloquear atividades de trabalhadores sem aptidão/autorização vigente até a regularização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
