insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('DC-01', 11, 'Menor — elevar a Maior se impedir atividade, liberação de etapa ou aceitação', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "eSocial/SST em dia" (item 11 do checklist DC-01 – Documentação Legal e de SSMA). Critério de aceitação aplicável: Eventos S-2210/2220/2240 sendo enviados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NRs aplicáveis (NR-01, NR-07, NR-10, NR-33, NR-35, entre outras) exigem documentação legal vigente na obra: PGR, PCMSO, ASOs, certificados de treinamento, autorizações formais e ARTs dos responsáveis técnicos. Referência-base aplicável: Documentação Legal e de SSMA · documento/manual do cliente quando aplicável. O critério "Eventos S-2210/2220/2240 sendo enviados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Documentação ausente ou vencida caracteriza trabalhadores não aptos/não autorizados em atividade, infração administrativa e nulidade de defesas em eventual acidente. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Eventos S-2210/2220/2240 sendo enviados"; (ii) regularizar os documentos pendentes e bloquear atividades de trabalhadores sem aptidão/autorização vigente até a regularização; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('VE-01', 1, 'Maior — elevar a Crítica se equipamento em uso com falha de segurança', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "CNH válida e compatível" (item 1 do checklist VE-01 – Veículos Leves e de Transporte). Critério de aceitação aplicável: Categoria correta, motorista autorizado. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O Código de Trânsito Brasileiro e os procedimentos internos exigem veículos licenciados, com checklist diário (DDR), manutenção em dia, condutores habilitados e regras de circulação interna (velocidade, prioridade de máquinas) cumpridas. Referência-base aplicável: Veículos Leves e de Transporte · documento/manual do cliente quando aplicável. O critério "Categoria correta, motorista autorizado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Veículos em más condições ou conduzidos irregularmente geram atropelamentos, colisões e tombamentos, principais eventos com vítimas em vias internas de obra. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Categoria correta, motorista autorizado"; (ii) retirar o veículo de circulação até adequação e reforçar as regras de trânsito interno com os condutores; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('VE-01', 2, 'Maior — elevar a Crítica se equipamento em uso com falha de segurança', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Checklist diário do veículo" (item 2 do checklist VE-01 – Veículos Leves e de Transporte). Critério de aceitação aplicável: Preenchido antes da saída. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O Código de Trânsito Brasileiro e os procedimentos internos exigem veículos licenciados, com checklist diário (DDR), manutenção em dia, condutores habilitados e regras de circulação interna (velocidade, prioridade de máquinas) cumpridas. Referência-base aplicável: Veículos Leves e de Transporte · documento/manual do cliente quando aplicável. O critério "Preenchido antes da saída" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Veículos em más condições ou conduzidos irregularmente geram atropelamentos, colisões e tombamentos, principais eventos com vítimas em vias internas de obra. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Preenchido antes da saída"; (ii) retirar o veículo de circulação até adequação e reforçar as regras de trânsito interno com os condutores; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
