insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('VE-01', 10, 'Maior — elevar a Crítica se equipamento em uso com falha de segurança', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Transporte de trabalhadores regular" (item 10 do checklist VE-01 – Veículos Leves e de Transporte). Critério de aceitação aplicável: Veículo apropriado, jamais em carroceria. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O Código de Trânsito Brasileiro e os procedimentos internos exigem veículos licenciados, com checklist diário (DDR), manutenção em dia, condutores habilitados e regras de circulação interna (velocidade, prioridade de máquinas) cumpridas. Referência-base aplicável: Veículos Leves e de Transporte · documento/manual do cliente quando aplicável. O critério "Veículo apropriado, jamais em carroceria" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Veículos em más condições ou conduzidos irregularmente geram atropelamentos, colisões e tombamentos, principais eventos com vítimas em vias internas de obra. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Veículo apropriado, jamais em carroceria"; (ii) retirar o veículo de circulação até adequação e reforçar as regras de trânsito interno com os condutores; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('SO-01', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Água potável em todas as frentes" (item 1 do checklist SO-01 – Saúde e Condições de Trabalho). Critério de aceitação aplicável: Fresca e acessível, copos individuais/garrafas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NR-21 e NR-24 exigem condições sanitárias e de conforto adequadas: instalações sanitárias limpas e suficientes, água potável acessível, refeitório adequado e proteção contra intempéries nas frentes. Referência-base aplicável: Saúde e Condições de Trabalho · documento/manual do cliente quando aplicável. O critério "Fresca e acessível, copos individuais/garrafas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Condições sanitárias precárias afetam a saúde e a dignidade dos trabalhadores, geram autuações trabalhistas e degradam clima e produtividade. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Fresca e acessível, copos individuais/garrafas"; (ii) adequar as instalações de vivência/campo com rotina de limpeza e suprimento verificáveis; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('SO-01', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Refeitório em condições higiênicas" (item 2 do checklist SO-01 – Saúde e Condições de Trabalho). Critério de aceitação aplicável: Conservação de alimentos, limpeza. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NR-21 e NR-24 exigem condições sanitárias e de conforto adequadas: instalações sanitárias limpas e suficientes, água potável acessível, refeitório adequado e proteção contra intempéries nas frentes. Referência-base aplicável: Saúde e Condições de Trabalho · documento/manual do cliente quando aplicável. O critério "Conservação de alimentos, limpeza" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Condições sanitárias precárias afetam a saúde e a dignidade dos trabalhadores, geram autuações trabalhistas e degradam clima e produtividade. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Conservação de alimentos, limpeza"; (ii) adequar as instalações de vivência/campo com rotina de limpeza e suprimento verificáveis; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
