insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('SO-01', 10, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Áreas de vivência (NR-24)" (item 10 do checklist SO-01 – Saúde e Condições de Trabalho). Critério de aceitação aplicável: Alojamento (se houver): camas, ventilação, limpeza. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NR-21 e NR-24 exigem condições sanitárias e de conforto adequadas: instalações sanitárias limpas e suficientes, água potável acessível, refeitório adequado e proteção contra intempéries nas frentes. Referência-base aplicável: Saúde e Condições de Trabalho · documento/manual do cliente quando aplicável. O critério "Alojamento (se houver): camas, ventilação, limpeza" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Condições sanitárias precárias afetam a saúde e a dignidade dos trabalhadores, geram autuações trabalhistas e degradam clima e produtividade. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Alojamento (se houver): camas, ventilação, limpeza"; (ii) adequar as instalações de vivência/campo com rotina de limpeza e suprimento verificáveis; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EM-01', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Plano de emergência disponível" (item 1 do checklist EM-01 – Preparação e Resposta a Emergências). Critério de aceitação aplicável: Atualizado, com cenários da obra. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-23 e o plano de emergência da obra exigem meios de combate a incêndio inspecionados e desobstruídos, rotas de fuga sinalizadas, brigada/equipe de resposta treinada e simulados registrados. Referência-base aplicável: Preparação e Resposta a Emergências · documento/manual do cliente quando aplicável. O critério "Atualizado, com cenários da obra" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas na preparação para emergências transformam eventos controláveis em ocorrências graves, ampliando danos a pessoas e ativos pela resposta tardia ou inadequada. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Atualizado, com cenários da obra"; (ii) restabelecer os meios de resposta (extintores, rotas, comunicação) e programar treinamento/simulado de reciclagem; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EM-01', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Brigada de emergência formada" (item 2 do checklist EM-01 – Preparação e Resposta a Emergências). Critério de aceitação aplicável: Brigadistas treinados e identificados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-23 e o plano de emergência da obra exigem meios de combate a incêndio inspecionados e desobstruídos, rotas de fuga sinalizadas, brigada/equipe de resposta treinada e simulados registrados. Referência-base aplicável: Preparação e Resposta a Emergências · documento/manual do cliente quando aplicável. O critério "Brigadistas treinados e identificados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas na preparação para emergências transformam eventos controláveis em ocorrências graves, ampliando danos a pessoas e ativos pela resposta tardia ou inadequada. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Brigadistas treinados e identificados"; (ii) restabelecer os meios de resposta (extintores, rotas, comunicação) e programar treinamento/simulado de reciclagem; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
