insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CT-01', 1, 'Menor — elevar a Maior se impedir atividade, liberação de etapa ou aceitação', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Documentação legal em dia" (item 1 do checklist CT-01 – Gestão de Subcontratadas). Critério de aceitação aplicável: Contrato, CNDs, seguros, FGTS/INSS. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 e as regras contratuais exigem gestão das subcontratadas: documentação de SSMA homologada, integração dos trabalhadores, equivalência de padrões de segurança e supervisão ativa da contratante. Referência-base aplicável: Gestão de Subcontratadas · documento/manual do cliente quando aplicável. O critério "Contrato, CNDs, seguros, FGTS/INSS" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Subcontratadas sem gestão adequada introduzem padrões inferiores de segurança e qualidade, e a responsabilidade solidária recai sobre a contratante em acidentes e passivos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Contrato, CNDs, seguros, FGTS/INSS"; (ii) notificar formalmente a subcontratada, exigir plano de adequação com prazo e condicionar a continuidade dos serviços ao atendimento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CT-01', 2, 'Menor — elevar a Maior se impedir atividade, liberação de etapa ou aceitação', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Integração de 100% do efetivo" (item 2 do checklist CT-01 – Gestão de Subcontratadas). Critério de aceitação aplicável: Registro antes do início das atividades. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NR-01 e as regras contratuais exigem gestão das subcontratadas: documentação de SSMA homologada, integração dos trabalhadores, equivalência de padrões de segurança e supervisão ativa da contratante. Referência-base aplicável: Gestão de Subcontratadas · documento/manual do cliente quando aplicável. O critério "Registro antes do início das atividades" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Subcontratadas sem gestão adequada introduzem padrões inferiores de segurança e qualidade, e a responsabilidade solidária recai sobre a contratante em acidentes e passivos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Registro antes do início das atividades"; (ii) notificar formalmente a subcontratada, exigir plano de adequação com prazo e condicionar a continuidade dos serviços ao atendimento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
