insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('PR-01', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Cronograma atualizado" (item 1 do checklist PR-01 – Andamento Físico da Obra). Critério de aceitação aplicável: Avanço físico real × planejado registrado. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O contrato e o cronograma físico aprovado (linha de base) estabelecem marcos, sequenciamento e avanço físico esperado, cabendo registro de desvios, tratativas de recuperação e atualização periódica das medições. Referência-base aplicável: Andamento Físico da Obra · documento/manual do cliente quando aplicável. O critério "Avanço físico real × planejado registrado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios de avanço não tratados comprometem marcos contratuais, geram pleitos e multas, e induzem aceleração de fim de obra com degradação de qualidade e segurança. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Avanço físico real × planejado registrado"; (ii) formalizar o desvio junto ao planejamento, avaliar plano de recuperação e registrar impactos em prazo/custo para gestão contratual; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('PR-01', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Frentes de serviço liberadas" (item 2 do checklist PR-01 – Andamento Físico da Obra). Critério de aceitação aplicável: Sem bloqueios documentais/técnicos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O contrato e o cronograma físico aprovado (linha de base) estabelecem marcos, sequenciamento e avanço físico esperado, cabendo registro de desvios, tratativas de recuperação e atualização periódica das medições. Referência-base aplicável: Andamento Físico da Obra · documento/manual do cliente quando aplicável. O critério "Sem bloqueios documentais/técnicos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios de avanço não tratados comprometem marcos contratuais, geram pleitos e multas, e induzem aceleração de fim de obra com degradação de qualidade e segurança. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Sem bloqueios documentais/técnicos"; (ii) formalizar o desvio junto ao planejamento, avaliar plano de recuperação e registrar impactos em prazo/custo para gestão contratual; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
