insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-01', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Topografia de referência conferida" (item 1 do checklist CV-01 – Terraplenagem). Critério de aceitação aplicável: Greides, platôs e off-sets conforme projeto na revisão vigente. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 7182 (ensaio de compactação — Proctor) e a especificação técnica do projeto estabelecem os requisitos de terraplenagem: material adequado, espessura de camadas, umidade e grau de compactação mínimo comprovados por ensaios de campo. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 7182 (Proctor); especificação técnica do projeto; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Greides, platôs e off-sets conforme projeto na revisão vigente" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aterros mal compactados sofrem recalques diferenciais que comprometem fundações, vias e estruturas apoiadas, com correção de alto custo após execução das etapas subsequentes. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Greides, platôs e off-sets conforme projeto na revisão vigente"; (ii) suspender o avanço sobre a camada questionada até comprovação por ensaios (grau de compactação/umidade) e reprocessar camadas reprovadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-01', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Material de aterro aprovado" (item 2 do checklist CV-01 – Terraplenagem). Critério de aceitação aplicável: Caracterização/CBR conforme especificação; jazida autorizada. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 7182 (ensaio de compactação — Proctor) e a especificação técnica do projeto estabelecem os requisitos de terraplenagem: material adequado, espessura de camadas, umidade e grau de compactação mínimo comprovados por ensaios de campo. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 7182 (Proctor); especificação técnica do projeto; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Caracterização/CBR conforme especificação; jazida autorizada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aterros mal compactados sofrem recalques diferenciais que comprometem fundações, vias e estruturas apoiadas, com correção de alto custo após execução das etapas subsequentes. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Caracterização/CBR conforme especificação; jazida autorizada"; (ii) suspender o avanço sobre a camada questionada até comprovação por ensaios (grau de compactação/umidade) e reprocessar camadas reprovadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-01', 3, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Compactação executada por camadas" (item 3 do checklist CV-01 – Terraplenagem). Critério de aceitação aplicável: Espessura solta ≤ especificada; nº de passadas do equipamento definido. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 7182 (ensaio de compactação — Proctor) e a especificação técnica do projeto estabelecem os requisitos de terraplenagem: material adequado, espessura de camadas, umidade e grau de compactação mínimo comprovados por ensaios de campo. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 7182 (Proctor); especificação técnica do projeto; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Espessura solta ≤ especificada; nº de passadas do equipamento definido" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aterros mal compactados sofrem recalques diferenciais que comprometem fundações, vias e estruturas apoiadas, com correção de alto custo após execução das etapas subsequentes. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Espessura solta ≤ especificada; nº de passadas do equipamento definido"; (ii) suspender o avanço sobre a camada questionada até comprovação por ensaios (grau de compactação/umidade) e reprocessar camadas reprovadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-01', 4, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Grau de compactação ensaiado" (item 4 do checklist CV-01 – Terraplenagem). Critério de aceitação aplicável: GC ≥ 95/98% do Proctor conforme projeto; frequência de ensaios atendida. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 7182 (ensaio de compactação — Proctor) e a especificação técnica do projeto estabelecem os requisitos de terraplenagem: material adequado, espessura de camadas, umidade e grau de compactação mínimo comprovados por ensaios de campo. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 7182 (Proctor); especificação técnica do projeto; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "GC ≥ 95/98% do Proctor conforme projeto; frequência de ensaios atendida" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aterros mal compactados sofrem recalques diferenciais que comprometem fundações, vias e estruturas apoiadas, com correção de alto custo após execução das etapas subsequentes. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "GC ≥ 95/98% do Proctor conforme projeto; frequência de ensaios atendida"; (ii) suspender o avanço sobre a camada questionada até comprovação por ensaios (grau de compactação/umidade) e reprocessar camadas reprovadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-01', 5, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Umidade na faixa ótima" (item 5 do checklist CV-01 – Terraplenagem). Critério de aceitação aplicável: Desvio dentro da tolerância (±2% típico) no momento da compactação. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 7182 (ensaio de compactação — Proctor) e a especificação técnica do projeto estabelecem os requisitos de terraplenagem: material adequado, espessura de camadas, umidade e grau de compactação mínimo comprovados por ensaios de campo. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 7182 (Proctor); especificação técnica do projeto; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Desvio dentro da tolerância (±2% típico) no momento da compactação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aterros mal compactados sofrem recalques diferenciais que comprometem fundações, vias e estruturas apoiadas, com correção de alto custo após execução das etapas subsequentes. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Desvio dentro da tolerância (±2% típico) no momento da compactação"; (ii) suspender o avanço sobre a camada questionada até comprovação por ensaios (grau de compactação/umidade) e reprocessar camadas reprovadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
