insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-03', 6, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Armadura conforme projeto" (item 6 do checklist CV-03 – Fundações (estacas, perfis e blocos)). Critério de aceitação aplicável: Bitolas, espaçamentos e cobrimento (blocos e sapatas). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 6122 e o relatório de sondagem estabelecem os requisitos de execução de fundações: locação e prumo, cota de assentamento/nega compatível com o previsto, integridade dos elementos e registros de cravação/concretagem por elemento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 6122; relatório de sondagem; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Bitolas, espaçamentos e cobrimento (blocos e sapatas)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Fundações executadas em desacordo com o projeto comprometem a capacidade de carga e a estabilidade da estrutura suportada, com correção extremamente onerosa após carregamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Bitolas, espaçamentos e cobrimento (blocos e sapatas)"; (ii) suspender o carregamento dos elementos questionados, avaliar com o projetista (aceite, reforço ou substituição) e registrar a disposição técnica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-03', 7, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Concreto conforme especificação" (item 7 do checklist CV-03 – Fundações (estacas, perfis e blocos)). Critério de aceitação aplicável: fck, slump e corpos de prova moldados (NBR 12655). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 6122 e o relatório de sondagem estabelecem os requisitos de execução de fundações: locação e prumo, cota de assentamento/nega compatível com o previsto, integridade dos elementos e registros de cravação/concretagem por elemento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 6122; relatório de sondagem; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "fck, slump e corpos de prova moldados (NBR 12655)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Fundações executadas em desacordo com o projeto comprometem a capacidade de carga e a estabilidade da estrutura suportada, com correção extremamente onerosa após carregamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "fck, slump e corpos de prova moldados (NBR 12655)"; (ii) suspender o carregamento dos elementos questionados, avaliar com o projetista (aceite, reforço ou substituição) e registrar a disposição técnica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-03', 8, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Ensaio de carga quando exigido" (item 8 do checklist CV-03 – Fundações (estacas, perfis e blocos)). Critério de aceitação aplicável: Estático/dinâmico conforme projeto. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 6122 e o relatório de sondagem estabelecem os requisitos de execução de fundações: locação e prumo, cota de assentamento/nega compatível com o previsto, integridade dos elementos e registros de cravação/concretagem por elemento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 6122; relatório de sondagem; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Estático/dinâmico conforme projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Fundações executadas em desacordo com o projeto comprometem a capacidade de carga e a estabilidade da estrutura suportada, com correção extremamente onerosa após carregamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Estático/dinâmico conforme projeto"; (ii) suspender o carregamento dos elementos questionados, avaliar com o projetista (aceite, reforço ou substituição) e registrar a disposição técnica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-03', 9, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Não conformidades geotécnicas tratadas" (item 9 do checklist CV-03 – Fundações (estacas, perfis e blocos)). Critério de aceitação aplicável: Solo divergente da sondagem → reprojeto/disposição registrada. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 6122 e o relatório de sondagem estabelecem os requisitos de execução de fundações: locação e prumo, cota de assentamento/nega compatível com o previsto, integridade dos elementos e registros de cravação/concretagem por elemento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 6122; relatório de sondagem; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Solo divergente da sondagem → reprojeto/disposição registrada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Fundações executadas em desacordo com o projeto comprometem a capacidade de carga e a estabilidade da estrutura suportada, com correção extremamente onerosa após carregamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Solo divergente da sondagem → reprojeto/disposição registrada"; (ii) suspender o carregamento dos elementos questionados, avaliar com o projetista (aceite, reforço ou substituição) e registrar a disposição técnica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-04', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Formas conferidas antes da concretagem" (item 1 do checklist CV-04 – Concreto Estrutural e Armação). Critério de aceitação aplicável: Geometria, estanqueidade, travamento e desmoldante. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 14931 (execução de estruturas de concreto), NBR 6118 (projeto) e NBR 12655 (preparo e controle do concreto) estabelecem requisitos de armação (bitola, espaçamento, cobrimento), formas, concretagem, cura e controle tecnológico por lotes. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14931; NBR 6118; NBR 12655; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Geometria, estanqueidade, travamento e desmoldante" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios em armação, cobrimento ou controle tecnológico reduzem a capacidade resistente e a durabilidade da estrutura, podendo exigir reforço estrutural ou demolição. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Geometria, estanqueidade, travamento e desmoldante"; (ii) bloquear a concretagem/liberação da peça até correção e reinspeção; para concreto aplicado, acionar controle tecnológico (rompimentos, esclerometria) e disposição do projetista; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-04', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Armadura conforme projeto" (item 2 do checklist CV-04 – Concreto Estrutural e Armação). Critério de aceitação aplicável: Bitola, espaçamento, amarração e emendas/transpasses. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 14931 (execução de estruturas de concreto), NBR 6118 (projeto) e NBR 12655 (preparo e controle do concreto) estabelecem requisitos de armação (bitola, espaçamento, cobrimento), formas, concretagem, cura e controle tecnológico por lotes. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14931; NBR 6118; NBR 12655; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Bitola, espaçamento, amarração e emendas/transpasses" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios em armação, cobrimento ou controle tecnológico reduzem a capacidade resistente e a durabilidade da estrutura, podendo exigir reforço estrutural ou demolição. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Bitola, espaçamento, amarração e emendas/transpasses"; (ii) bloquear a concretagem/liberação da peça até correção e reinspeção; para concreto aplicado, acionar controle tecnológico (rompimentos, esclerometria) e disposição do projetista; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
