insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-04', 7, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Lançamento e adensamento corretos" (item 7 do checklist CV-04 – Concreto Estrutural e Armação). Critério de aceitação aplicável: Altura de lançamento, vibração sem segregação. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 14931 (execução de estruturas de concreto), NBR 6118 (projeto) e NBR 12655 (preparo e controle do concreto) estabelecem requisitos de armação (bitola, espaçamento, cobrimento), formas, concretagem, cura e controle tecnológico por lotes. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14931; NBR 6118; NBR 12655; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Altura de lançamento, vibração sem segregação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios em armação, cobrimento ou controle tecnológico reduzem a capacidade resistente e a durabilidade da estrutura, podendo exigir reforço estrutural ou demolição. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Altura de lançamento, vibração sem segregação"; (ii) bloquear a concretagem/liberação da peça até correção e reinspeção; para concreto aplicado, acionar controle tecnológico (rompimentos, esclerometria) e disposição do projetista; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-04', 8, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Juntas de concretagem tratadas" (item 8 do checklist CV-04 – Concreto Estrutural e Armação). Critério de aceitação aplicável: Localização e preparo conforme projeto. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 14931 (execução de estruturas de concreto), NBR 6118 (projeto) e NBR 12655 (preparo e controle do concreto) estabelecem requisitos de armação (bitola, espaçamento, cobrimento), formas, concretagem, cura e controle tecnológico por lotes. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14931; NBR 6118; NBR 12655; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Localização e preparo conforme projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios em armação, cobrimento ou controle tecnológico reduzem a capacidade resistente e a durabilidade da estrutura, podendo exigir reforço estrutural ou demolição. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Localização e preparo conforme projeto"; (ii) bloquear a concretagem/liberação da peça até correção e reinspeção; para concreto aplicado, acionar controle tecnológico (rompimentos, esclerometria) e disposição do projetista; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
