insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-05', 6, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Ausência de erosões e ravinas" (item 6 do checklist CV-05 – Drenagem Definitiva). Critério de aceitação aplicável: Inspeção após chuvas significativas registrada. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de drenagem aprovado estabelece dispositivos, seções, declividades, cotas e proteções (enrocamento, dissipadores) necessários ao funcionamento hidráulico e à proteção contra erosão do empreendimento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de drenagem aprovado; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Inspeção após chuvas significativas registrada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Drenagem executada em desacordo com o projeto perde eficiência hidráulica, gerando erosões, assoreamento e danos progressivos a vias, taludes e estruturas — padrão de deterioração recorrente em UFVs. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Inspeção após chuvas significativas registrada"; (ii) corrigir o dispositivo conforme projeto (seção, cota, proteção) e verificar funcionalmente o trecho após chuva ou teste de escoamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CV-05', 7, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Sistema desassoreado" (item 7 do checklist CV-05 – Drenagem Definitiva). Critério de aceitação aplicável: Limpeza de canaletas e caixas em dia. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de drenagem aprovado estabelece dispositivos, seções, declividades, cotas e proteções (enrocamento, dissipadores) necessários ao funcionamento hidráulico e à proteção contra erosão do empreendimento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de drenagem aprovado; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Limpeza de canaletas e caixas em dia" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Drenagem executada em desacordo com o projeto perde eficiência hidráulica, gerando erosões, assoreamento e danos progressivos a vias, taludes e estruturas — padrão de deterioração recorrente em UFVs. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Limpeza de canaletas e caixas em dia"; (ii) corrigir o dispositivo conforme projeto (seção, cota, proteção) e verificar funcionalmente o trecho após chuva ou teste de escoamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
