insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-01', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Componentes recebidos e conferidos" (item 1 do checklist ME-01 – Montagem de Trackers e Estruturas FV). Critério de aceitação aplicável: Romaneio × projeto; danos de transporte registrados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante do tracker e o projeto executivo estabelecem torque de fixações, alinhamento e nivelamento, folgas e binários de montagem, e requisitos de aterramento/equipotencialização das estruturas fotovoltaicas. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante do tracker; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Romaneio × projeto; danos de transporte registrados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Montagem fora das tolerâncias do fabricante compromete o rastreamento, gera esforços não previstos, perda de garantia e falhas estruturais sob vento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Romaneio × projeto; danos de transporte registrados"; (ii) corrigir a montagem conforme manual (torque com ferramenta calibrada, alinhamento) e registrar em ficha de verificação rastreável por eixo/fileira; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-01', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Alinhamento e prumo das fileiras" (item 2 do checklist ME-01 – Montagem de Trackers e Estruturas FV). Critério de aceitação aplicável: Tolerâncias do fabricante conferidas (topografia). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante do tracker e o projeto executivo estabelecem torque de fixações, alinhamento e nivelamento, folgas e binários de montagem, e requisitos de aterramento/equipotencialização das estruturas fotovoltaicas. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante do tracker; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Tolerâncias do fabricante conferidas (topografia)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Montagem fora das tolerâncias do fabricante compromete o rastreamento, gera esforços não previstos, perda de garantia e falhas estruturais sob vento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Tolerâncias do fabricante conferidas (topografia)"; (ii) corrigir a montagem conforme manual (torque com ferramenta calibrada, alinhamento) e registrar em ficha de verificação rastreável por eixo/fileira; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
