insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-01', 8, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Tolerâncias finais do fabricante atendidas" (item 8 do checklist ME-01 – Montagem de Trackers e Estruturas FV). Critério de aceitação aplicável: Checklist do fabricante preenchido por fileira. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante do tracker e o projeto executivo estabelecem torque de fixações, alinhamento e nivelamento, folgas e binários de montagem, e requisitos de aterramento/equipotencialização das estruturas fotovoltaicas. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante do tracker; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Checklist do fabricante preenchido por fileira" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Montagem fora das tolerâncias do fabricante compromete o rastreamento, gera esforços não previstos, perda de garantia e falhas estruturais sob vento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Checklist do fabricante preenchido por fileira"; (ii) corrigir a montagem conforme manual (torque com ferramenta calibrada, alinhamento) e registrar em ficha de verificação rastreável por eixo/fileira; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-02', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Manuseio conforme manual" (item 1 do checklist ME-02 – Instalação de Módulos Fotovoltaicos). Critério de aceitação aplicável: Sem apoio indevido, flexão ou pisoteio de módulos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante do módulo e a NBR 16274 estabelecem requisitos de instalação de módulos fotovoltaicos: manuseio sem sobrecarga pontual, fixação com torque/clamps especificados, ausência de células danificadas e conectores adequadamente acoplados. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante do módulo; NBR 16274; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Sem apoio indevido, flexão ou pisoteio de módulos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Módulos com microtrincas, fixação inadequada ou conectores mal acoplados geram perda de geração, pontos quentes com risco de incêndio e perda de garantia do fabricante. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Sem apoio indevido, flexão ou pisoteio de módulos"; (ii) substituir/reinstalar módulos afetados conforme manual, inspecionar lote por amostragem e registrar séries dos módulos trocados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-02', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Inspeção visual no recebimento/instalação" (item 2 do checklist ME-02 – Instalação de Módulos Fotovoltaicos). Critério de aceitação aplicável: Vidro, backsheet e caixa de junção íntegros; quebras registradas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante do módulo e a NBR 16274 estabelecem requisitos de instalação de módulos fotovoltaicos: manuseio sem sobrecarga pontual, fixação com torque/clamps especificados, ausência de células danificadas e conectores adequadamente acoplados. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante do módulo; NBR 16274; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Vidro, backsheet e caixa de junção íntegros; quebras registradas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Módulos com microtrincas, fixação inadequada ou conectores mal acoplados geram perda de geração, pontos quentes com risco de incêndio e perda de garantia do fabricante. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Vidro, backsheet e caixa de junção íntegros; quebras registradas"; (ii) substituir/reinstalar módulos afetados conforme manual, inspecionar lote por amostragem e registrar séries dos módulos trocados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-02', 3, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Clamps na posição e torque corretos" (item 3 do checklist ME-02 – Instalação de Módulos Fotovoltaicos). Critério de aceitação aplicável: Zona de fixação e torque do manual atendidos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante do módulo e a NBR 16274 estabelecem requisitos de instalação de módulos fotovoltaicos: manuseio sem sobrecarga pontual, fixação com torque/clamps especificados, ausência de células danificadas e conectores adequadamente acoplados. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante do módulo; NBR 16274; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Zona de fixação e torque do manual atendidos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Módulos com microtrincas, fixação inadequada ou conectores mal acoplados geram perda de geração, pontos quentes com risco de incêndio e perda de garantia do fabricante. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Zona de fixação e torque do manual atendidos"; (ii) substituir/reinstalar módulos afetados conforme manual, inspecionar lote por amostragem e registrar séries dos módulos trocados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-02', 4, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Serialização registrada" (item 4 do checklist ME-02 – Instalação de Módulos Fotovoltaicos). Critério de aceitação aplicável: Nº de série vinculado a string/fileira (rastreabilidade). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante do módulo e a NBR 16274 estabelecem requisitos de instalação de módulos fotovoltaicos: manuseio sem sobrecarga pontual, fixação com torque/clamps especificados, ausência de células danificadas e conectores adequadamente acoplados. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante do módulo; NBR 16274; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Nº de série vinculado a string/fileira (rastreabilidade)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Módulos com microtrincas, fixação inadequada ou conectores mal acoplados geram perda de geração, pontos quentes com risco de incêndio e perda de garantia do fabricante. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Nº de série vinculado a string/fileira (rastreabilidade)"; (ii) substituir/reinstalar módulos afetados conforme manual, inspecionar lote por amostragem e registrar séries dos módulos trocados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-02', 5, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Strings com polaridade e sequência corretas" (item 5 do checklist ME-02 – Instalação de Módulos Fotovoltaicos). Critério de aceitação aplicável: Conforme projeto elétrico; etiquetagem aplicada. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante do módulo e a NBR 16274 estabelecem requisitos de instalação de módulos fotovoltaicos: manuseio sem sobrecarga pontual, fixação com torque/clamps especificados, ausência de células danificadas e conectores adequadamente acoplados. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante do módulo; NBR 16274; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Conforme projeto elétrico; etiquetagem aplicada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Módulos com microtrincas, fixação inadequada ou conectores mal acoplados geram perda de geração, pontos quentes com risco de incêndio e perda de garantia do fabricante. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Conforme projeto elétrico; etiquetagem aplicada"; (ii) substituir/reinstalar módulos afetados conforme manual, inspecionar lote por amostragem e registrar séries dos módulos trocados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
