insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-03', 6, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Supervisão do fabricante quando exigida" (item 6 do checklist ME-03 – Içamento e Posicionamento de Equipamentos (execução)). Critério de aceitação aplicável: Presença registrada (garantia preservada). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O plano de rigging aprovado e o manual do fabricante estabelecem os requisitos de içamento e posicionamento: pontos de içamento corretos, acessórios dimensionados, sequência de montagem e tolerâncias de posicionamento/nivelamento do equipamento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Plano de rigging aprovado; manual do fabricante; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Presença registrada (garantia preservada)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Içamento fora do plano pode danificar o equipamento (dano oculto de transporte/manuseio) e gerar acidente grave; posicionamento incorreto compromete interfaces de montagem subsequentes. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Presença registrada (garantia preservada)"; (ii) suspender a operação até revalidação do plano de rigging e conferir posicionamento final com controle dimensional registrado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-04', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "EPS aprovada disponível na frente" (item 1 do checklist ME-04 – Soldagem e Caldeiraria). Critério de aceitação aplicável: Procedimento compatível com material e junta. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As EPS/RQPS aprovadas e o código de projeto (AWS/ASME) estabelecem os requisitos de soldagem: soldadores qualificados, consumíveis controlados, parâmetros conforme EPS, inspeção visual e END conforme plano de inspeção. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: EPS/RQPS aprovadas; código de projeto (AWS/ASME); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Procedimento compatível com material e junta" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Soldas executadas fora de procedimento apresentam defeitos (falta de fusão, trincas) que podem levar a falha estrutural ou de estanqueidade em serviço, com reparo de alto custo. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Procedimento compatível com material e junta"; (ii) bloquear a junta questionada, executar END conforme plano, reparar por soldador qualificado seguindo procedimento de reparo aprovado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-04', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Soldadores qualificados" (item 2 do checklist ME-04 – Soldagem e Caldeiraria). Critério de aceitação aplicável: RQPS válido para o processo/posição. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As EPS/RQPS aprovadas e o código de projeto (AWS/ASME) estabelecem os requisitos de soldagem: soldadores qualificados, consumíveis controlados, parâmetros conforme EPS, inspeção visual e END conforme plano de inspeção. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: EPS/RQPS aprovadas; código de projeto (AWS/ASME); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "RQPS válido para o processo/posição" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Soldas executadas fora de procedimento apresentam defeitos (falta de fusão, trincas) que podem levar a falha estrutural ou de estanqueidade em serviço, com reparo de alto custo. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "RQPS válido para o processo/posição"; (ii) bloquear a junta questionada, executar END conforme plano, reparar por soldador qualificado seguindo procedimento de reparo aprovado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
