insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-04', 8, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Trabalho a quente com PT" (item 8 do checklist ME-04 – Soldagem e Caldeiraria). Critério de aceitação aplicável: Interface ST-13 atendida. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As EPS/RQPS aprovadas e o código de projeto (AWS/ASME) estabelecem os requisitos de soldagem: soldadores qualificados, consumíveis controlados, parâmetros conforme EPS, inspeção visual e END conforme plano de inspeção. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: EPS/RQPS aprovadas; código de projeto (AWS/ASME); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Interface ST-13 atendida" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Soldas executadas fora de procedimento apresentam defeitos (falta de fusão, trincas) que podem levar a falha estrutural ou de estanqueidade em serviço, com reparo de alto custo. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Interface ST-13 atendida"; (ii) bloquear a junta questionada, executar END conforme plano, reparar por soldador qualificado seguindo procedimento de reparo aprovado; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-05', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Base e nivelamento conferidos" (item 1 do checklist ME-05 – Montagem Mecânica de Equipamentos). Critério de aceitação aplicável: Conforme desenho certificado do fabricante. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante estabelece os requisitos de montagem mecânica: sequência e torques especificados, nivelamento/alinhamento dentro de tolerâncias, lubrificantes e fluidos corretos e preservação dos internos até o comissionamento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Conforme desenho certificado do fabricante" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Montagem fora do manual gera falha prematura do equipamento, perda de garantia do fabricante e retrabalho em fase de comissionamento com impacto direto no caminho crítico. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Conforme desenho certificado do fabricante"; (ii) corrigir a montagem conforme manual com presença/validação da assistência técnica do fabricante quando contratualmente prevista; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-05', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Alinhamento de acoplamentos executado" (item 2 do checklist ME-05 – Montagem Mecânica de Equipamentos). Critério de aceitação aplicável: Relatório de alinhamento quando aplicável. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante estabelece os requisitos de montagem mecânica: sequência e torques especificados, nivelamento/alinhamento dentro de tolerâncias, lubrificantes e fluidos corretos e preservação dos internos até o comissionamento. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Relatório de alinhamento quando aplicável" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Montagem fora do manual gera falha prematura do equipamento, perda de garantia do fabricante e retrabalho em fase de comissionamento com impacto direto no caminho crítico. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Relatório de alinhamento quando aplicável"; (ii) corrigir a montagem conforme manual com presença/validação da assistência técnica do fabricante quando contratualmente prevista; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
