insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-06', 5, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Retoques de galvanização executados" (item 5 do checklist ME-06 – Pintura e Tratamento Anticorrosivo). Critério de aceitação aplicável: Produto e espessura conforme norma. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A especificação de pintura do projeto e as normas aplicáveis estabelecem preparo de superfície, condições ambientais de aplicação, espessuras de película (EPS/EPD) medidas e reparos de danos conforme esquema de pintura. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Especificação de pintura do projeto; normas aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Produto e espessura conforme norma" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Pintura aplicada fora de especificação falha precocemente (corrosão prematura), comprometendo a vida útil dos ativos e gerando custos recorrentes de manutenção. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Produto e espessura conforme norma"; (ii) reparar o trecho conforme esquema de pintura (preparo + reaplicação) com medição de espessuras registrada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ME-06', 6, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Identificação final aplicada" (item 6 do checklist ME-06 – Pintura e Tratamento Anticorrosivo). Critério de aceitação aplicável: TAGs e cores de segurança (interface NR-26). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A especificação de pintura do projeto e as normas aplicáveis estabelecem preparo de superfície, condições ambientais de aplicação, espessuras de película (EPS/EPD) medidas e reparos de danos conforme esquema de pintura. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Especificação de pintura do projeto; normas aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "TAGs e cores de segurança (interface NR-26)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Pintura aplicada fora de especificação falha precocemente (corrosão prematura), comprometendo a vida útil dos ativos e gerando custos recorrentes de manutenção. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "TAGs e cores de segurança (interface NR-26)"; (ii) reparar o trecho conforme esquema de pintura (preparo + reaplicação) com medição de espessuras registrada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-01', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Rotas e valas conforme projeto" (item 1 do checklist EL-01 – Lançamento de Cabos BT/CC). Critério de aceitação aplicável: Profundidade, envelope, fita de advertência e separações. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 5410 e o projeto executivo estabelecem os requisitos de lançamento de cabos BT/CC: rotas e segregação conforme projeto, raios de curvatura e esforços de tração respeitados, proteção mecânica e identificação dos circuitos. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 5410; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Profundidade, envelope, fita de advertência e separações" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Cabos danificados no lançamento ou instalados fora de projeto apresentam falhas de isolação em operação, geram desligamentos, retrabalho de difícil localização e risco de incêndio. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Profundidade, envelope, fita de advertência e separações"; (ii) substituir/reparar trechos danificados, adequar rotas e identificação conforme projeto e registrar megger dos circuitos afetados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-01', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Raios de curvatura respeitados" (item 2 do checklist EL-01 – Lançamento de Cabos BT/CC). Critério de aceitação aplicável: Conforme fabricante do cabo. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 5410 e o projeto executivo estabelecem os requisitos de lançamento de cabos BT/CC: rotas e segregação conforme projeto, raios de curvatura e esforços de tração respeitados, proteção mecânica e identificação dos circuitos. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 5410; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Conforme fabricante do cabo" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Cabos danificados no lançamento ou instalados fora de projeto apresentam falhas de isolação em operação, geram desligamentos, retrabalho de difícil localização e risco de incêndio. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Conforme fabricante do cabo"; (ii) substituir/reparar trechos danificados, adequar rotas e identificação conforme projeto e registrar megger dos circuitos afetados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
