insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-04', 8, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Laudo de aterramento emitido" (item 8 do checklist EL-04 – Aterramento e SPDA). Critério de aceitação aplicável: Assinado por responsável técnico com ART. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 5419 (proteção contra descargas atmosféricas) e NBR 15751 (aterramento de subestações) e o projeto executivo estabelecem os requisitos de malha de aterramento, equipotencialização das estruturas, SPDA e comprovação por medições com laudo assinado por responsável técnico. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 5419; NBR 15751; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Assinado por responsável técnico com ART" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aterramento deficiente expõe pessoas a tensões de passo e toque perigosas e deixa equipamentos vulneráveis a surtos e descargas atmosféricas, com risco de fatalidade e danos extensos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Assinado por responsável técnico com ART"; (ii) completar/corrigir as conexões e a malha conforme projeto, repetir as medições no trecho afetado e emitir/atualizar o laudo de aterramento com ART; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-05', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Fixação e base conforme fabricante" (item 1 do checklist EL-05 – Painéis, Inversores e Cubículos). Critério de aceitação aplicável: Nivelamento e torque de fixação. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os manuais dos fabricantes e o projeto executivo estabelecem os requisitos de instalação de painéis, inversores e cubículos: fixação e nivelamento, ajuste de portas e vedações (grau IP), conexões conforme diagramas, identificação e limpeza interna. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manuais dos fabricantes; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Nivelamento e torque de fixação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Equipamentos mal instalados ou com vedação comprometida sofrem ingresso de poeira/água e falhas prematuras, além de risco de operação indevida por identificação incorreta. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Nivelamento e torque de fixação"; (ii) adequar instalação e vedações conforme manual, conferir conexões contra diagramas e restabelecer identificação e limpeza antes do comissionamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-05', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Entradas de cabos vedadas" (item 2 do checklist EL-05 – Painéis, Inversores e Cubículos). Critério de aceitação aplicável: Prensa-cabos/selagem preservando grau IP. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os manuais dos fabricantes e o projeto executivo estabelecem os requisitos de instalação de painéis, inversores e cubículos: fixação e nivelamento, ajuste de portas e vedações (grau IP), conexões conforme diagramas, identificação e limpeza interna. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manuais dos fabricantes; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Prensa-cabos/selagem preservando grau IP" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Equipamentos mal instalados ou com vedação comprometida sofrem ingresso de poeira/água e falhas prematuras, além de risco de operação indevida por identificação incorreta. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Prensa-cabos/selagem preservando grau IP"; (ii) adequar instalação e vedações conforme manual, conferir conexões contra diagramas e restabelecer identificação e limpeza antes do comissionamento; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
