insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-06', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Barramentos montados conforme projeto" (item 1 do checklist EL-06 – Subestação — Montagem Eletromecânica Primária). Critério de aceitação aplicável: Torque, flechas e conexões conferidos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 14039, a IEC 62271 (manobra e comando de alta-tensão) e o projeto executivo estabelecem os requisitos da montagem eletromecânica primária de subestação: locação e nivelamento de equipamentos, distâncias elétricas de segurança, conexões de alta tensão e aterramentos conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14039; IEC 62271; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Torque, flechas e conexões conferidos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios na montagem primária (distâncias, conexões, nivelamento) comprometem a suportabilidade dielétrica e a segurança operacional da subestação, com risco de falha catastrófica na energização. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Torque, flechas e conexões conferidos"; (ii) corrigir a montagem conforme projeto com controle dimensional das distâncias elétricas e liberação formal de engenharia antes dos testes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-06', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Distâncias elétricas verificadas" (item 2 do checklist EL-06 – Subestação — Montagem Eletromecânica Primária). Critério de aceitação aplicável: Fase-fase e fase-terra conforme projeto/norma. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 14039, a IEC 62271 (manobra e comando de alta-tensão) e o projeto executivo estabelecem os requisitos da montagem eletromecânica primária de subestação: locação e nivelamento de equipamentos, distâncias elétricas de segurança, conexões de alta tensão e aterramentos conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14039; IEC 62271; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Fase-fase e fase-terra conforme projeto/norma" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios na montagem primária (distâncias, conexões, nivelamento) comprometem a suportabilidade dielétrica e a segurança operacional da subestação, com risco de falha catastrófica na energização. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Fase-fase e fase-terra conforme projeto/norma"; (ii) corrigir a montagem conforme projeto com controle dimensional das distâncias elétricas e liberação formal de engenharia antes dos testes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-06', 3, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Seccionadoras ajustadas" (item 3 do checklist EL-06 – Subestação — Montagem Eletromecânica Primária). Critério de aceitação aplicável: Curso, alinhamento de contatos e comandos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 14039, a IEC 62271 (manobra e comando de alta-tensão) e o projeto executivo estabelecem os requisitos da montagem eletromecânica primária de subestação: locação e nivelamento de equipamentos, distâncias elétricas de segurança, conexões de alta tensão e aterramentos conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14039; IEC 62271; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Curso, alinhamento de contatos e comandos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios na montagem primária (distâncias, conexões, nivelamento) comprometem a suportabilidade dielétrica e a segurança operacional da subestação, com risco de falha catastrófica na energização. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Curso, alinhamento de contatos e comandos"; (ii) corrigir a montagem conforme projeto com controle dimensional das distâncias elétricas e liberação formal de engenharia antes dos testes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('EL-06', 4, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Disjuntores instalados conforme fabricante" (item 4 do checklist EL-06 – Subestação — Montagem Eletromecânica Primária). Critério de aceitação aplicável: Pressão SF6/molas, comandos e sinalizações. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 14039, a IEC 62271 (manobra e comando de alta-tensão) e o projeto executivo estabelecem os requisitos da montagem eletromecânica primária de subestação: locação e nivelamento de equipamentos, distâncias elétricas de segurança, conexões de alta tensão e aterramentos conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14039; IEC 62271; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Pressão SF6/molas, comandos e sinalizações" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desvios na montagem primária (distâncias, conexões, nivelamento) comprometem a suportabilidade dielétrica e a segurança operacional da subestação, com risco de falha catastrófica na energização. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Pressão SF6/molas, comandos e sinalizações"; (ii) corrigir a montagem conforme projeto com controle dimensional das distâncias elétricas e liberação formal de engenharia antes dos testes; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
