insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-02', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Procedimentos de teste aprovados" (item 1 do checklist CM-02 – Testes a Frio — Elétrica). Critério de aceitação aplicável: Critérios de aceitação definidos antes do teste. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os planos de teste aprovados e as NBR/IEC aplicáveis estabelecem os testes a frio de elétrica: resistência de isolamento, continuidade, relação de transformação, resistência de contatos e demais ensaios com instrumentos calibrados e resultados dentro dos critérios de aceitação. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Planos de teste aprovados; NBR/IEC aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Critérios de aceitação definidos antes do teste" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Testes a frio omitidos ou com resultados fora do critério deixam defeitos latentes que se manifestam na energização, com risco de dano irreversível a equipamentos de alto valor. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Critérios de aceitação definidos antes do teste"; (ii) repetir o ensaio questionado com instrumento calibrado, investigar resultados fora do critério e obter disposição de engenharia antes de prosseguir; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-02', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Instrumentos calibrados" (item 2 do checklist CM-02 – Testes a Frio — Elétrica). Critério de aceitação aplicável: Certificados RBC válidos anexados aos relatórios. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os planos de teste aprovados e as NBR/IEC aplicáveis estabelecem os testes a frio de elétrica: resistência de isolamento, continuidade, relação de transformação, resistência de contatos e demais ensaios com instrumentos calibrados e resultados dentro dos critérios de aceitação. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Planos de teste aprovados; NBR/IEC aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Certificados RBC válidos anexados aos relatórios" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Testes a frio omitidos ou com resultados fora do critério deixam defeitos latentes que se manifestam na energização, com risco de dano irreversível a equipamentos de alto valor. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Certificados RBC válidos anexados aos relatórios"; (ii) repetir o ensaio questionado com instrumento calibrado, investigar resultados fora do critério e obter disposição de engenharia antes de prosseguir; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-02', 3, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Resistência de isolamento medida" (item 3 do checklist CM-02 – Testes a Frio — Elétrica). Critério de aceitação aplicável: Valores ≥ critério (norma/fabricante) por equipamento. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os planos de teste aprovados e as NBR/IEC aplicáveis estabelecem os testes a frio de elétrica: resistência de isolamento, continuidade, relação de transformação, resistência de contatos e demais ensaios com instrumentos calibrados e resultados dentro dos critérios de aceitação. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Planos de teste aprovados; NBR/IEC aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Valores ≥ critério (norma/fabricante) por equipamento" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Testes a frio omitidos ou com resultados fora do critério deixam defeitos latentes que se manifestam na energização, com risco de dano irreversível a equipamentos de alto valor. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Valores ≥ critério (norma/fabricante) por equipamento"; (ii) repetir o ensaio questionado com instrumento calibrado, investigar resultados fora do critério e obter disposição de engenharia antes de prosseguir; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-02', 4, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "TTR de transformadores executado" (item 4 do checklist CM-02 – Testes a Frio — Elétrica). Critério de aceitação aplicável: Relação em todas as derivações × placa. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os planos de teste aprovados e as NBR/IEC aplicáveis estabelecem os testes a frio de elétrica: resistência de isolamento, continuidade, relação de transformação, resistência de contatos e demais ensaios com instrumentos calibrados e resultados dentro dos critérios de aceitação. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Planos de teste aprovados; NBR/IEC aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Relação em todas as derivações × placa" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Testes a frio omitidos ou com resultados fora do critério deixam defeitos latentes que se manifestam na energização, com risco de dano irreversível a equipamentos de alto valor. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Relação em todas as derivações × placa"; (ii) repetir o ensaio questionado com instrumento calibrado, investigar resultados fora do critério e obter disposição de engenharia antes de prosseguir; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
