insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-02', 8, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Relatórios assinados por sistema" (item 8 do checklist CM-02 – Testes a Frio — Elétrica). Critério de aceitação aplicável: Assinaturas de executante e fiscalização. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os planos de teste aprovados e as NBR/IEC aplicáveis estabelecem os testes a frio de elétrica: resistência de isolamento, continuidade, relação de transformação, resistência de contatos e demais ensaios com instrumentos calibrados e resultados dentro dos critérios de aceitação. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Planos de teste aprovados; NBR/IEC aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Assinaturas de executante e fiscalização" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Testes a frio omitidos ou com resultados fora do critério deixam defeitos latentes que se manifestam na energização, com risco de dano irreversível a equipamentos de alto valor. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Assinaturas de executante e fiscalização"; (ii) repetir o ensaio questionado com instrumento calibrado, investigar resultados fora do critério e obter disposição de engenharia antes de prosseguir; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-03', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Ajustes conforme estudo de seletividade" (item 1 do checklist CM-03 – Proteção, Controle e Automação (SAS)). Critério de aceitação aplicável: Arquivo de parametrização × estudo conferido. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O estudo de seletividade vigente, a IEC 61850 e os Submódulos 2.11/2.12 do ONS estabelecem os requisitos de proteção, controle e automação: parametrização conforme estudo, testes funcionais de proteção, intertravamentos e sinalização SAS ponto a ponto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Estudo de seletividade (rev. vigente); IEC 61850; ONS Submód. 2.11/2.12; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Arquivo de parametrização × estudo conferido" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Proteções mal parametrizadas ou não testadas podem não atuar (dano catastrófico ao equipamento) ou atuar indevidamente (desligamentos e penalidades), comprometendo pessoas e ativos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Arquivo de parametrização × estudo conferido"; (ii) revalidar a parametrização contra o estudo de seletividade vigente e reexecutar os testes funcionais afetados com registros por função de proteção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-03', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Injeção secundária executada" (item 2 do checklist CM-03 – Proteção, Controle e Automação (SAS)). Critério de aceitação aplicável: Pickup e tempos das funções (50/51/87/21/27/59) conforme ajuste. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O estudo de seletividade vigente, a IEC 61850 e os Submódulos 2.11/2.12 do ONS estabelecem os requisitos de proteção, controle e automação: parametrização conforme estudo, testes funcionais de proteção, intertravamentos e sinalização SAS ponto a ponto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Estudo de seletividade (rev. vigente); IEC 61850; ONS Submód. 2.11/2.12; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Pickup e tempos das funções (50/51/87/21/27/59) conforme ajuste" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Proteções mal parametrizadas ou não testadas podem não atuar (dano catastrófico ao equipamento) ou atuar indevidamente (desligamentos e penalidades), comprometendo pessoas e ativos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Pickup e tempos das funções (50/51/87/21/27/59) conforme ajuste"; (ii) revalidar a parametrização contra o estudo de seletividade vigente e reexecutar os testes funcionais afetados com registros por função de proteção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-03', 3, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Injeção primária quando exigida" (item 3 do checklist CM-03 – Proteção, Controle e Automação (SAS)). Critério de aceitação aplicável: Circuitos de TC comprovados fio a fio. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O estudo de seletividade vigente, a IEC 61850 e os Submódulos 2.11/2.12 do ONS estabelecem os requisitos de proteção, controle e automação: parametrização conforme estudo, testes funcionais de proteção, intertravamentos e sinalização SAS ponto a ponto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Estudo de seletividade (rev. vigente); IEC 61850; ONS Submód. 2.11/2.12; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Circuitos de TC comprovados fio a fio" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Proteções mal parametrizadas ou não testadas podem não atuar (dano catastrófico ao equipamento) ou atuar indevidamente (desligamentos e penalidades), comprometendo pessoas e ativos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Circuitos de TC comprovados fio a fio"; (ii) revalidar a parametrização contra o estudo de seletividade vigente e reexecutar os testes funcionais afetados com registros por função de proteção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-03', 4, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Mensagens GOOSE testadas" (item 4 do checklist CM-03 – Proteção, Controle e Automação (SAS)). Critério de aceitação aplicável: Intertravamentos e trips via IEC 61850 verificados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O estudo de seletividade vigente, a IEC 61850 e os Submódulos 2.11/2.12 do ONS estabelecem os requisitos de proteção, controle e automação: parametrização conforme estudo, testes funcionais de proteção, intertravamentos e sinalização SAS ponto a ponto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Estudo de seletividade (rev. vigente); IEC 61850; ONS Submód. 2.11/2.12; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Intertravamentos e trips via IEC 61850 verificados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Proteções mal parametrizadas ou não testadas podem não atuar (dano catastrófico ao equipamento) ou atuar indevidamente (desligamentos e penalidades), comprometendo pessoas e ativos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Intertravamentos e trips via IEC 61850 verificados"; (ii) revalidar a parametrização contra o estudo de seletividade vigente e reexecutar os testes funcionais afetados com registros por função de proteção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-03', 5, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Lógicas e intertravamentos validados" (item 5 do checklist CM-03 – Proteção, Controle e Automação (SAS)). Critério de aceitação aplicável: Matriz de trip testada cenário a cenário. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O estudo de seletividade vigente, a IEC 61850 e os Submódulos 2.11/2.12 do ONS estabelecem os requisitos de proteção, controle e automação: parametrização conforme estudo, testes funcionais de proteção, intertravamentos e sinalização SAS ponto a ponto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Estudo de seletividade (rev. vigente); IEC 61850; ONS Submód. 2.11/2.12; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Matriz de trip testada cenário a cenário" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Proteções mal parametrizadas ou não testadas podem não atuar (dano catastrófico ao equipamento) ou atuar indevidamente (desligamentos e penalidades), comprometendo pessoas e ativos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Matriz de trip testada cenário a cenário"; (ii) revalidar a parametrização contra o estudo de seletividade vigente e reexecutar os testes funcionais afetados com registros por função de proteção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-03', 6, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Telecomandos e sinalizações ao SCADA" (item 6 do checklist CM-03 – Proteção, Controle e Automação (SAS)). Critério de aceitação aplicável: Comando/estado ponto a ponto com o supervisório (interface TC-04). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O estudo de seletividade vigente, a IEC 61850 e os Submódulos 2.11/2.12 do ONS estabelecem os requisitos de proteção, controle e automação: parametrização conforme estudo, testes funcionais de proteção, intertravamentos e sinalização SAS ponto a ponto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Estudo de seletividade (rev. vigente); IEC 61850; ONS Submód. 2.11/2.12; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Comando/estado ponto a ponto com o supervisório (interface TC-04)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Proteções mal parametrizadas ou não testadas podem não atuar (dano catastrófico ao equipamento) ou atuar indevidamente (desligamentos e penalidades), comprometendo pessoas e ativos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Comando/estado ponto a ponto com o supervisório (interface TC-04)"; (ii) revalidar a parametrização contra o estudo de seletividade vigente e reexecutar os testes funcionais afetados com registros por função de proteção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-03', 7, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Oscilografia configurada" (item 7 do checklist CM-03 – Proteção, Controle e Automação (SAS)). Critério de aceitação aplicável: Registro de perturbação habilitado e testado. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O estudo de seletividade vigente, a IEC 61850 e os Submódulos 2.11/2.12 do ONS estabelecem os requisitos de proteção, controle e automação: parametrização conforme estudo, testes funcionais de proteção, intertravamentos e sinalização SAS ponto a ponto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Estudo de seletividade (rev. vigente); IEC 61850; ONS Submód. 2.11/2.12; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Registro de perturbação habilitado e testado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Proteções mal parametrizadas ou não testadas podem não atuar (dano catastrófico ao equipamento) ou atuar indevidamente (desligamentos e penalidades), comprometendo pessoas e ativos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Registro de perturbação habilitado e testado"; (ii) revalidar a parametrização contra o estudo de seletividade vigente e reexecutar os testes funcionais afetados com registros por função de proteção; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-04', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "PT específica de energização emitida" (item 1 do checklist CM-04 – Energização). Critério de aceitação aplicável: Análise de risco da manobra assinada. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O procedimento de energização aprovado e os requisitos do ONS/concessionária estabelecem as condições de energização: pré-requisitos verificados, comunicações e autorizações formais, sequência de manobras validada e área isolada com equipe reduzida. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Procedimento de energização aprovado; requisitos ONS/concessionária; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Análise de risco da manobra assinada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Energização sem pré-requisitos plenamente atendidos é o momento de maior risco do empreendimento — falhas nesta etapa historicamente resultam em acidentes graves e danos a equipamentos principais. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Análise de risco da manobra assinada"; (ii) suspender a energização até atendimento integral do procedimento (checklist de pré-energização, autorizações, isolamento) com aprovação formal do responsável técnico; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-04', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Checklist pré-energização concluído" (item 2 do checklist CM-04 – Energização). Critério de aceitação aplicável: Corpos estranhos e ferramentas removidos das áreas energizáveis. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O procedimento de energização aprovado e os requisitos do ONS/concessionária estabelecem as condições de energização: pré-requisitos verificados, comunicações e autorizações formais, sequência de manobras validada e área isolada com equipe reduzida. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Procedimento de energização aprovado; requisitos ONS/concessionária; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Corpos estranhos e ferramentas removidos das áreas energizáveis" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Energização sem pré-requisitos plenamente atendidos é o momento de maior risco do empreendimento — falhas nesta etapa historicamente resultam em acidentes graves e danos a equipamentos principais. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Corpos estranhos e ferramentas removidos das áreas energizáveis"; (ii) suspender a energização até atendimento integral do procedimento (checklist de pré-energização, autorizações, isolamento) com aprovação formal do responsável técnico; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
