insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-04', 7, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Monitoramento pós-energização" (item 7 do checklist CM-04 – Energização). Critério de aceitação aplicável: Acompanhamento nas primeiras horas; termografia inicial. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O procedimento de energização aprovado e os requisitos do ONS/concessionária estabelecem as condições de energização: pré-requisitos verificados, comunicações e autorizações formais, sequência de manobras validada e área isolada com equipe reduzida. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Procedimento de energização aprovado; requisitos ONS/concessionária; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Acompanhamento nas primeiras horas; termografia inicial" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Energização sem pré-requisitos plenamente atendidos é o momento de maior risco do empreendimento — falhas nesta etapa historicamente resultam em acidentes graves e danos a equipamentos principais. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Acompanhamento nas primeiras horas; termografia inicial"; (ii) suspender a energização até atendimento integral do procedimento (checklist de pré-energização, autorizações, isolamento) com aprovação formal do responsável técnico; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-05', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Testes funcionais em carga executados" (item 1 do checklist CM-05 – Testes a Quente e Performance). Critério de aceitação aplicável: Inversores/sistemas operando conforme fabricante. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As IEC 62446 e IEC 61724 e os requisitos contratuais estabelecem os testes a quente e de performance: verificações funcionais energizadas, curva de capacidade/performance ratio conforme contrato e monitoramento validado. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: IEC 62446; IEC 61724; requisitos contratuais; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Inversores/sistemas operando conforme fabricante" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Performance abaixo do contratado sem detecção nos testes gera disputas contratuais e perda de receita recorrente; falhas funcionais a quente não tratadas comprometem a operação comercial. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Inversores/sistemas operando conforme fabricante"; (ii) investigar tecnicamente o desvio de performance/funcional, corrigir a causa raiz e reexecutar o teste com critérios e período contratuais; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-05', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Curvas I-V amostrais de strings" (item 2 do checklist CM-05 – Testes a Quente e Performance). Critério de aceitação aplicável: Amostragem conforme plano; desvios investigados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As IEC 62446 e IEC 61724 e os requisitos contratuais estabelecem os testes a quente e de performance: verificações funcionais energizadas, curva de capacidade/performance ratio conforme contrato e monitoramento validado. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: IEC 62446; IEC 61724; requisitos contratuais; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Amostragem conforme plano; desvios investigados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Performance abaixo do contratado sem detecção nos testes gera disputas contratuais e perda de receita recorrente; falhas funcionais a quente não tratadas comprometem a operação comercial. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Amostragem conforme plano; desvios investigados"; (ii) investigar tecnicamente o desvio de performance/funcional, corrigir a causa raiz e reexecutar o teste com critérios e período contratuais; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção p