insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-06', 4, 'Menor — elevar a Maior se impedir atividade, liberação de etapa ou aceitação', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "ARTs recolhidas" (item 4 do checklist CM-06 – TAC/TAF e Documentação Final). Critério de aceitação aplicável: Execução, fiscalização e projetos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O contrato e o Submódulo 11.4 do ONS (quando aplicável) estabelecem os requisitos de TAC/TAF e documentação final: pendências fechadas ou negociadas, data books completos, as-builts, laudos, garantias e termos de aceitação formalizados. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Contrato; ONS Submódulo 11.4 (quando aplicável); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Execução, fiscalização e projetos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aceitação sem documentação completa transfere passivos ocultos ao proprietário/O&M, dificulta manutenção futura e enfraquece a posição contratual em garantias. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Execução, fiscalização e projetos"; (ii) completar o data book/as-built pendente e condicionar a assinatura do termo de aceitação à verificação documental integral; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('CM-06', 5, 'Menor — elevar a Maior se impedir atividade, liberação de etapa ou aceitação', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Certificados de calibração anexados" (item 5 do checklist CM-06 – TAC/TAF e Documentação Final). Critério de aceitação aplicável: Instrumentos usados nos testes rastreáveis. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O contrato e o Submódulo 11.4 do ONS (quando aplicável) estabelecem os requisitos de TAC/TAF e documentação final: pendências fechadas ou negociadas, data books completos, as-builts, laudos, garantias e termos de aceitação formalizados. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Contrato; ONS Submódulo 11.4 (quando aplicável); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Instrumentos usados nos testes rastreáveis" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aceitação sem documentação completa transfere passivos ocultos ao proprietário/O&M, dificulta manutenção futura e enfraquece a posição contratual em garantias. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Instrumentos usados nos testes rastreáveis"; (ii) completar o data book/as-built pendente e condicionar a assinatura do termo de aceitação à verificação documental integral; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
