insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-02', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Locação de pernas conferida" (item 1 do checklist LT-02 – Fundações de Torres). Critério de aceitação aplicável: Topografia por torre dentro das tolerâncias. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 6122 e o projeto executivo estabelecem os requisitos das fundações de torres: geometria e cotas por perna, concreto com controle tecnológico, stubs/chumbadores posicionados dentro das tolerâncias e reaterro compactado. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 6122; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Topografia por torre dentro das tolerâncias" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Fundações de torre fora de tolerância introduzem esforços não previstos na estrutura, podendo levar à falha da torre sob carregamento de vento ou tracionamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Topografia por torre dentro das tolerâncias"; (ii) verificar topograficamente as pernas afetadas, submeter desvios ao projetista para disposição e corrigir antes do içamento da torre; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-02', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Escavação conforme tipo de fundação" (item 2 do checklist LT-02 – Fundações de Torres). Critério de aceitação aplicável: Tubulão/grelha/sapata conforme solo real × projeto. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 6122 e o projeto executivo estabelecem os requisitos das fundações de torres: geometria e cotas por perna, concreto com controle tecnológico, stubs/chumbadores posicionados dentro das tolerâncias e reaterro compactado. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 6122; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Tubulão/grelha/sapata conforme solo real × projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Fundações de torre fora de tolerância introduzem esforços não previstos na estrutura, podendo levar à falha da torre sob carregamento de vento ou tracionamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Tubulão/grelha/sapata conforme solo real × projeto"; (ii) verificar topograficamente as pernas afetadas, submeter desvios ao projetista para disposição e corrigir antes do içamento da torre; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-02', 3, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Armadura e concreto conforme projeto" (item 3 do checklist LT-02 – Fundações de Torres). Critério de aceitação aplicável: Interface CV-04 aplicada por fundação. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 6122 e o projeto executivo estabelecem os requisitos das fundações de torres: geometria e cotas por perna, concreto com controle tecnológico, stubs/chumbadores posicionados dentro das tolerâncias e reaterro compactado. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 6122; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Interface CV-04 aplicada por fundação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Fundações de torre fora de tolerância introduzem esforços não previstos na estrutura, podendo levar à falha da torre sob carregamento de vento ou tracionamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Interface CV-04 aplicada por fundação"; (ii) verificar topograficamente as pernas afetadas, submeter desvios ao projetista para disposição e corrigir antes do içamento da torre; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
