insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-03', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Peças conferidas por romaneio" (item 1 do checklist LT-03 – Montagem de Torres). Critério de aceitação aplicável: Componentes por torre completos e íntegros. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de montagem estabelece os requisitos de montagem de torres: peças conforme lista e projeto, torque dos parafusos com ferramenta calibrada, verticalidade dentro da tolerância e integridade das peças (sem deformações ou danos de galvanização). A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de montagem; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Componentes por torre completos e íntegros" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Torres com montagem deficiente (peças trocadas, torque inadequado, prumo fora) apresentam risco estrutural sob carga e retrabalho de grande complexidade após lançamento dos cabos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Componentes por torre completos e íntegros"; (ii) corrigir a montagem conforme projeto (torque registrado, prumo conferido) antes do lançamento e nivelamento final dos cabos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-03', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Pré-montagem conforme sequência" (item 2 do checklist LT-03 – Montagem de Torres). Critério de aceitação aplicável: Método executivo aprovado seguido. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de montagem estabelece os requisitos de montagem de torres: peças conforme lista e projeto, torque dos parafusos com ferramenta calibrada, verticalidade dentro da tolerância e integridade das peças (sem deformações ou danos de galvanização). A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de montagem; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Método executivo aprovado seguido" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Torres com montagem deficiente (peças trocadas, torque inadequado, prumo fora) apresentam risco estrutural sob carga e retrabalho de grande complexidade após lançamento dos cabos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Método executivo aprovado seguido"; (ii) corrigir a montagem conforme projeto (torque registrado, prumo conferido) antes do lançamento e nivelamento final dos cabos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
