insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-05', 5, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Registro por vão alimentado" (item 5 do checklist LT-05 – Cadeias, Ferragens e Acessórios). Critério de aceitação aplicável: Conferência documentada por tramo. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto e os catálogos dos fabricantes estabelecem os requisitos de cadeias, ferragens e acessórios: componentes corretos por família de estrutura, montagem e travamento (contrapinos, split pins), torques e amortecedores/espaçadores posicionados conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto; catálogos dos fabricantes; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Conferência documentada por tramo" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Ferragens incorretas ou mal travadas levam a desgaste acelerado, falha de cadeia e queda de condutor, evento de alto impacto operacional e de segurança. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Conferência documentada por tramo"; (ii) corrigir/completar os componentes conforme projeto com inspeção de travamento registrada por estrutura; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-06', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Contrapesos conforme resistividade" (item 1 do checklist LT-06 – Aterramento e Contrapesos). Critério de aceitação aplicável: Configuração por torre conforme medições de solo. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 5422 e o projeto de aterramento estabelecem os requisitos de aterramento e contrapesos: configuração por estrutura conforme projeto, conexões adequadas, valores de resistência medidos e registrados por torre. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 5422; projeto de aterramento; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Configuração por torre conforme medições de solo" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Aterramento de torres deficiente eleva desligamentos por descargas atmosféricas (backflashover) e riscos de tensões perigosas junto às estruturas. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Configuração por torre conforme medições de solo"; (ii) completar/corrigir contrapesos e conexões conforme projeto e repetir a medição de resistência nas estruturas afetadas; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
