insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-07', 1, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Inspeção final da faixa concluída" (item 1 do checklist LT-07 – Comissionamento e Energização de LT). Critério de aceitação aplicável: Altura de vegetação e obstáculos conforme critério. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os procedimentos do ONS/concessionária estabelecem os requisitos de comissionamento e energização da LT: verificações finais (distâncias, faixas, aterramentos temporários removidos), comunicações formais e sequência de energização autorizada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Procedimentos ONS/concessionária; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Altura de vegetação e obstáculos conforme critério" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Energizar LT com pendências (aterramentos temporários, invasões de faixa, distâncias) pode causar acidentes fatais com terceiros e desligamentos imediatos com penalidades. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Altura de vegetação e obstáculos conforme critério"; (ii) suspender a energização até verificação integral da linha e formalização das autorizações junto ao centro de operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-07', 2, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Pendências impeditivas zeradas" (item 2 do checklist LT-07 – Comissionamento e Energização de LT). Critério de aceitação aplicável: Punch A da LT resolvido. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os procedimentos do ONS/concessionária estabelecem os requisitos de comissionamento e energização da LT: verificações finais (distâncias, faixas, aterramentos temporários removidos), comunicações formais e sequência de energização autorizada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Procedimentos ONS/concessionária; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Punch A da LT resolvido" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Energizar LT com pendências (aterramentos temporários, invasões de faixa, distâncias) pode causar acidentes fatais com terceiros e desligamentos imediatos com penalidades. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Punch A da LT resolvido"; (ii) suspender a energização até verificação integral da linha e formalização das autorizações junto ao centro de operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-07', 3, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Medições finais executadas" (item 3 do checklist LT-07 – Comissionamento e Energização de LT). Critério de aceitação aplicável: Continuidade, aterramentos e verificações de fase. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os procedimentos do ONS/concessionária estabelecem os requisitos de comissionamento e energização da LT: verificações finais (distâncias, faixas, aterramentos temporários removidos), comunicações formais e sequência de energização autorizada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Procedimentos ONS/concessionária; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Continuidade, aterramentos e verificações de fase" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Energizar LT com pendências (aterramentos temporários, invasões de faixa, distâncias) pode causar acidentes fatais com terceiros e desligamentos imediatos com penalidades. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Continuidade, aterramentos e verificações de fase"; (ii) suspender a energização até verificação integral da linha e formalização das autorizações junto ao centro de operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-07', 4, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Coordenação de energização formalizada" (item 4 do checklist LT-07 – Comissionamento e Energização de LT). Critério de aceitação aplicável: ONS/concessionária com horários e manobras aprovados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os procedimentos do ONS/concessionária estabelecem os requisitos de comissionamento e energização da LT: verificações finais (distâncias, faixas, aterramentos temporários removidos), comunicações formais e sequência de energização autorizada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Procedimentos ONS/concessionária; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "ONS/concessionária com horários e manobras aprovados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Energizar LT com pendências (aterramentos temporários, invasões de faixa, distâncias) pode causar acidentes fatais com terceiros e desligamentos imediatos com penalidades. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "ONS/concessionária com horários e manobras aprovados"; (ii) suspender a energização até verificação integral da linha e formalização das autorizações junto ao centro de operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('LT-07', 5, 'Maior — elevar a Crítica em caso de risco grave e iminente (paralisação imediata)', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Patrulhamento pós-energização" (item 5 do checklist LT-07 – Comissionamento e Energização de LT). Critério de aceitação aplicável: Inspeção da linha nas primeiras horas/dias registrada. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os procedimentos do ONS/concessionária estabelecem os requisitos de comissionamento e energização da LT: verificações finais (distâncias, faixas, aterramentos temporários removidos), comunicações formais e sequência de energização autorizada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Procedimentos ONS/concessionária; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Inspeção da linha nas primeiras horas/dias registrada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Energizar LT com pendências (aterramentos temporários, invasões de faixa, distâncias) pode causar acidentes fatais com terceiros e desligamentos imediatos com penalidades. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Inspeção da linha nas primeiras horas/dias registrada"; (ii) suspender a energização até verificação integral da linha e formalização das autorizações junto ao centro de operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('TC-01', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Dutos e caixas conforme projeto" (item 1 do checklist TC-01 – Infraestrutura de Telecomunicações). Critério de aceitação aplicável: Rotas, ocupação e cordoalhas-guia. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 14565 e o projeto executivo estabelecem os requisitos de infraestrutura de telecomunicações: encaminhamentos (eletrocalhas, dutos) conforme projeto, segregação de cabos, ocupação máxima e identificação da infraestrutura. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14565; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Rotas, ocupação e cordoalhas-guia" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Infraestrutura inadequada compromete a integridade dos cabos de comunicação e dificulta expansões e manutenção, afetando sistemas críticos de supervisão. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Rotas, ocupação e cordoalhas-guia"; (ii) adequar encaminhamentos e segregação conforme projeto antes do lançamento/aceitação dos cabos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('TC-01', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Sala técnica adequada" (item 2 do checklist TC-01 – Infraestrutura de Telecomunicações). Critério de aceitação aplicável: Climatização, piso, vedação e DPS instalados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 14565 e o projeto executivo estabelecem os requisitos de infraestrutura de telecomunicações: encaminhamentos (eletrocalhas, dutos) conforme projeto, segregação de cabos, ocupação máxima e identificação da infraestrutura. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14565; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Climatização, piso, vedação e DPS instalados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Infraestrutura inadequada compromete a integridade dos cabos de comunicação e dificulta expansões e manutenção, afetando sistemas críticos de supervisão. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Climatização, piso, vedação e DPS instalados"; (ii) adequar encaminhamentos e segregação conforme projeto antes do lançamento/aceitação dos cabos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
