insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('TC-04', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Lista de pontos conferida ponto a ponto" (item 1 do checklist TC-04 – SCADA e Telecontrole). Critério de aceitação aplicável: Comandos, estados e medições × supervisório. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A lista de pontos aprovada, as IEC 60870-5-104/IEC 61850 e os requisitos do ONS estabelecem os requisitos de SCADA e telecontrole: pontos testados ponto a ponto contra a lista, comandos verificados com intertravamentos e comunicação com centros de operação validada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Lista de pontos aprovada; IEC 60870-5-104 / IEC 61850; requisitos ONS; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Comandos, estados e medições × supervisório" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Pontos de supervisão/comando incorretos induzem operação errada de equipamentos de potência, com potencial de dano grave e violação de requisitos do ONS. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Comandos, estados e medições × supervisório"; (ii) reexecutar o teste ponto a ponto dos sinais afetados com registro assinado e validação junto ao centro de operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('TC-04', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Protocolos testados" (item 2 do checklist TC-04 – SCADA e Telecontrole). Critério de aceitação aplicável: 104/61850 conforme arquitetura do projeto. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A lista de pontos aprovada, as IEC 60870-5-104/IEC 61850 e os requisitos do ONS estabelecem os requisitos de SCADA e telecontrole: pontos testados ponto a ponto contra a lista, comandos verificados com intertravamentos e comunicação com centros de operação validada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Lista de pontos aprovada; IEC 60870-5-104 / IEC 61850; requisitos ONS; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "104/61850 conforme arquitetura do projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Pontos de supervisão/comando incorretos induzem operação errada de equipamentos de potência, com potencial de dano grave e violação de requisitos do ONS. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "104/61850 conforme arquitetura do projeto"; (ii) reexecutar o teste ponto a ponto dos sinais afetados com registro assinado e validação junto ao centro de operação; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
