insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-01', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Blocos conforme especificação" (item 1 do checklist ED-01 – Alvenaria e Vedações). Critério de aceitação aplicável: Tipo, resistência e lote conferidos no recebimento. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 15812/15961 (alvenaria estrutural/vedação) e o memorial descritivo estabelecem os requisitos de alvenaria e vedações: modulação e prumo/nível/alinhamento dentro das tolerâncias, argamassa especificada, amarrações, vergas e contravergas conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 15812/15961 (alvenaria); memorial descritivo; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Tipo, resistência e lote conferidos no recebimento" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Alvenarias fora de prumo/esquadro ou sem vergas adequadas geram fissuras, retrabalho de revestimentos e patologias recorrentes pós-entrega. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Tipo, resistência e lote conferidos no recebimento"; (ii) corrigir os panos afetados (reexecução ou tratamento conforme orientação técnica) antes do fechamento com revestimentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-01', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Marcação e primeira fiada conferidas" (item 2 do checklist ED-01 – Alvenaria e Vedações). Critério de aceitação aplicável: Esquadro e alinhamento a partir de eixos topográficos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 15812/15961 (alvenaria estrutural/vedação) e o memorial descritivo estabelecem os requisitos de alvenaria e vedações: modulação e prumo/nível/alinhamento dentro das tolerâncias, argamassa especificada, amarrações, vergas e contravergas conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 15812/15961 (alvenaria); memorial descritivo; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Esquadro e alinhamento a partir de eixos topográficos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Alvenarias fora de prumo/esquadro ou sem vergas adequadas geram fissuras, retrabalho de revestimentos e patologias recorrentes pós-entrega. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Esquadro e alinhamento a partir de eixos topográficos"; (ii) corrigir os panos afetados (reexecução ou tratamento conforme orientação técnica) antes do fechamento com revestimentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
