insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-01', 4, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Amarração e juntas defasadas" (item 4 do checklist ED-01 – Alvenaria e Vedações). Critério de aceitação aplicável: Amarração entre panos e com estrutura conforme projeto. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 15812/15961 (alvenaria estrutural/vedação) e o memorial descritivo estabelecem os requisitos de alvenaria e vedações: modulação e prumo/nível/alinhamento dentro das tolerâncias, argamassa especificada, amarrações, vergas e contravergas conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 15812/15961 (alvenaria); memorial descritivo; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Amarração entre panos e com estrutura conforme projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Alvenarias fora de prumo/esquadro ou sem vergas adequadas geram fissuras, retrabalho de revestimentos e patologias recorrentes pós-entrega. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Amarração entre panos e com estrutura conforme projeto"; (ii) corrigir os panos afetados (reexecução ou tratamento conforme orientação técnica) antes do fechamento com revestimentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-01', 5, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Vergas e contravergas executadas" (item 5 do checklist ED-01 – Alvenaria e Vedações). Critério de aceitação aplicável: Em todos os vãos, com apoios mínimos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 15812/15961 (alvenaria estrutural/vedação) e o memorial descritivo estabelecem os requisitos de alvenaria e vedações: modulação e prumo/nível/alinhamento dentro das tolerâncias, argamassa especificada, amarrações, vergas e contravergas conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 15812/15961 (alvenaria); memorial descritivo; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Em todos os vãos, com apoios mínimos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Alvenarias fora de prumo/esquadro ou sem vergas adequadas geram fissuras, retrabalho de revestimentos e patologias recorrentes pós-entrega. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Em todos os vãos, com apoios mínimos"; (ii) corrigir os panos afetados (reexecução ou tratamento conforme orientação técnica) antes do fechamento com revestimentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-01', 6, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Fixação superior (encunhamento) correta" (item 6 do checklist ED-01 – Alvenaria e Vedações). Critério de aceitação aplicável: Material e prazo conforme projeto (após deformação da estrutura). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 15812/15961 (alvenaria estrutural/vedação) e o memorial descritivo estabelecem os requisitos de alvenaria e vedações: modulação e prumo/nível/alinhamento dentro das tolerâncias, argamassa especificada, amarrações, vergas e contravergas conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 15812/15961 (alvenaria); memorial descritivo; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Material e prazo conforme projeto (após deformação da estrutura)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Alvenarias fora de prumo/esquadro ou sem vergas adequadas geram fissuras, retrabalho de revestimentos e patologias recorrentes pós-entrega. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Material e prazo conforme projeto (após deformação da estrutura)"; (ii) corrigir os panos afetados (reexecução ou tratamento conforme orientação técnica) antes do fechamento com revestimentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-01', 7, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Embutimentos coordenados" (item 7 do checklist ED-01 – Alvenaria e Vedações). Critério de aceitação aplicável: Rasgos limitados; passagens compatibilizadas com instalações. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 15812/15961 (alvenaria estrutural/vedação) e o memorial descritivo estabelecem os requisitos de alvenaria e vedações: modulação e prumo/nível/alinhamento dentro das tolerâncias, argamassa especificada, amarrações, vergas e contravergas conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 15812/15961 (alvenaria); memorial descritivo; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Rasgos limitados; passagens compatibilizadas com instalações" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Alvenarias fora de prumo/esquadro ou sem vergas adequadas geram fissuras, retrabalho de revestimentos e patologias recorrentes pós-entrega. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Rasgos limitados; passagens compatibilizadas com instalações"; (ii) corrigir os panos afetados (reexecução ou tratamento conforme orientação técnica) antes do fechamento com revestimentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-01', 8, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Argamassa de assentamento conforme" (item 8 do checklist ED-01 – Alvenaria e Vedações). Critério de aceitação aplicável: Traço/industrializada conforme especificação. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 15812/15961 (alvenaria estrutural/vedação) e o memorial descritivo estabelecem os requisitos de alvenaria e vedações: modulação e prumo/nível/alinhamento dentro das tolerâncias, argamassa especificada, amarrações, vergas e contravergas conforme projeto. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 15812/15961 (alvenaria); memorial descritivo; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Traço/industrializada conforme especificação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Alvenarias fora de prumo/esquadro ou sem vergas adequadas geram fissuras, retrabalho de revestimentos e patologias recorrentes pós-entrega. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Traço/industrializada conforme especificação"; (ii) corrigir os panos afetados (reexecução ou tratamento conforme orientação técnica) antes do fechamento com revestimentos; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-02', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Sistema conforme projeto" (item 1 do checklist ED-02 – Impermeabilização). Critério de aceitação aplicável: Tipo de manta/membrana por área conforme NBR 9575. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 9575 (projeto) e NBR 9574 (execução de impermeabilização) e o projeto específico estabelecem preparo de substrato, tipo e espessura do sistema, detalhes de rodapés/ralos/juntas e teste de estanqueidade antes da proteção mecânica. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 9575/9574; projeto de impermeabilização; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Tipo de manta/membrana por área conforme NBR 9575" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas de impermeabilização são das patologias mais onerosas da construção: infiltrações atingem unidades e estruturas, e a correção exige demolição de acabamentos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Tipo de manta/membrana por área conforme NBR 9575"; (ii) refazer o trecho conforme projeto e repetir o teste de estanqueidade (72h) com registro fotográfico antes de liberar a proteção mecânica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-02', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Substrato preparado" (item 2 do checklist ED-02 – Impermeabilização). Critério de aceitação aplicável: Regularização com caimento, limpo e curado. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 9575 (projeto) e NBR 9574 (execução de impermeabilização) e o projeto específico estabelecem preparo de substrato, tipo e espessura do sistema, detalhes de rodapés/ralos/juntas e teste de estanqueidade antes da proteção mecânica. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 9575/9574; projeto de impermeabilização; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Regularização com caimento, limpo e curado" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas de impermeabilização são das patologias mais onerosas da construção: infiltrações atingem unidades e estruturas, e a correção exige demolição de acabamentos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Regularização com caimento, limpo e curado"; (ii) refazer o trecho conforme projeto e repetir o teste de estanqueidade (72h) com registro fotográfico antes de liberar a proteção mecânica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-02', 3, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Detalhes críticos executados" (item 3 do checklist ED-02 – Impermeabilização). Critério de aceitação aplicável: Ralos, tubos emergentes e cantos reforçados; subida ≥ 30 cm nas paredes. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 9575 (projeto) e NBR 9574 (execução de impermeabilização) e o projeto específico estabelecem preparo de substrato, tipo e espessura do sistema, detalhes de rodapés/ralos/juntas e teste de estanqueidade antes da proteção mecânica. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 9575/9574; projeto de impermeabilização; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Ralos, tubos emergentes e cantos reforçados; subida ≥ 30 cm nas paredes" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas de impermeabilização são das patologias mais onerosas da construção: infiltrações atingem unidades e estruturas, e a correção exige demolição de acabamentos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Ralos, tubos emergentes e cantos reforçados; subida ≥ 30 cm nas paredes"; (ii) refazer o trecho conforme projeto e repetir o teste de estanqueidade (72h) com registro fotográfico antes de liberar a proteção mecânica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-02', 4, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Consumo e demãos conforme fabricante" (item 4 do checklist ED-02 – Impermeabilização). Critério de aceitação aplicável: Espessura/nº de demãos registrados. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 9575 (projeto) e NBR 9574 (execução de impermeabilização) e o projeto específico estabelecem preparo de substrato, tipo e espessura do sistema, detalhes de rodapés/ralos/juntas e teste de estanqueidade antes da proteção mecânica. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 9575/9574; projeto de impermeabilização; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Espessura/nº de demãos registrados" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Falhas de impermeabilização são das patologias mais onerosas da construção: infiltrações atingem unidades e estruturas, e a correção exige demolição de acabamentos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Espessura/nº de demãos registrados"; (ii) refazer o trecho conforme projeto e repetir o teste de estanqueidade (72h) com registro fotográfico antes de liberar a proteção mecânica; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
