insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-04', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Eletrodutos e caixas conforme projeto" (item 1 do checklist ED-04 – Instalações Elétricas Prediais). Critério de aceitação aplicável: Ocupação máxima, alinhamento e nivelamento de caixas. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 5410, a NBR 5419 (SPDA) e o projeto elétrico aprovado estabelecem os requisitos das instalações elétricas prediais: circuitos, proteções (DR/DPS) e seções conforme projeto, aterramento e equipotencialização, e identificação dos quadros. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 5410; NBR 5419 (SPDA); projeto elétrico aprovado; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Ocupação máxima, alinhamento e nivelamento de caixas" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Instalações elétricas prediais fora de norma expõem usuários a choque e incêndio, e reprovam vistorias de concessionária e bombeiros, atrasando o habite-se. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Ocupação máxima, alinhamento e nivelamento de caixas"; (ii) adequar circuitos e proteções conforme projeto/NBR 5410 e evidenciar por ensaios (continuidade, isolamento, atuação de DR); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-04', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Enfiação após fases úmidas" (item 2 do checklist ED-04 – Instalações Elétricas Prediais). Critério de aceitação aplicável: Condutores íntegros, com folga e identificação. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 5410, a NBR 5419 (SPDA) e o projeto elétrico aprovado estabelecem os requisitos das instalações elétricas prediais: circuitos, proteções (DR/DPS) e seções conforme projeto, aterramento e equipotencialização, e identificação dos quadros. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 5410; NBR 5419 (SPDA); projeto elétrico aprovado; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Condutores íntegros, com folga e identificação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Instalações elétricas prediais fora de norma expõem usuários a choque e incêndio, e reprovam vistorias de concessionária e bombeiros, atrasando o habite-se. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Condutores íntegros, com folga e identificação"; (ii) adequar circuitos e proteções conforme projeto/NBR 5410 e evidenciar por ensaios (continuidade, isolamento, atuação de DR); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
