insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-06', 6, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Vidros conforme especificação" (item 6 do checklist ED-06 – Esquadrias e Vidros). Critério de aceitação aplicável: Tipo/espessura (temperado/laminado) conforme NBR 7199. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 10821 (esquadrias) e NBR 7199 (vidros na construção) estabelecem os requisitos de esquadrias e vidros: fixação e vedação estanques, funcionamento suave, vidros com espessura/tipo conforme projeto (temperado/laminado onde exigido) e desempenho acústico quando especificado. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 10821 (esquadrias); NBR 7199 (vidros); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Tipo/espessura (temperado/laminado) conforme NBR 7199" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Esquadrias com vedação deficiente geram infiltrações recorrentes; vidros fora de especificação em áreas de risco podem causar acidentes graves com usuários. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Tipo/espessura (temperado/laminado) conforme NBR 7199"; (ii) corrigir fixação/vedação e substituir vidros fora de especificação, com teste de estanqueidade por aspersão quando aplicável; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-06', 7, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Estanqueidade verificada" (item 7 do checklist ED-06 – Esquadrias e Vidros). Critério de aceitação aplicável: Teste de jato d''água quando exigido. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 10821 (esquadrias) e NBR 7199 (vidros na construção) estabelecem os requisitos de esquadrias e vidros: fixação e vedação estanques, funcionamento suave, vidros com espessura/tipo conforme projeto (temperado/laminado onde exigido) e desempenho acústico quando especificado. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 10821 (esquadrias); NBR 7199 (vidros); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Teste de jato d''água quando exigido" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Esquadrias com vedação deficiente geram infiltrações recorrentes; vidros fora de especificação em áreas de risco podem causar acidentes graves com usuários. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Teste de jato d''água quando exigido"; (ii) corrigir fixação/vedação e substituir vidros fora de especificação, com teste de estanqueidade por aspersão quando aplicável; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-07', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Estrutura de apoio conforme projeto" (item 1 do checklist ED-07 – Cobertura e Telhados). Critério de aceitação aplicável: Madeira/metálica com tratamento e fixações. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de cobertura e o manual do fabricante das telhas estabelecem os requisitos: estrutura e fixações conforme projeto, recobrimentos e inclinação mínimos, rufos/calhas dimensionados e fixados, e estanqueidade verificada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de cobertura; manual do fabricante das telhas; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Madeira/metálica com tratamento e fixações" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Coberturas com recobrimento ou fixação inadequados sofrem destelhamento sob vento e infiltrações generalizadas, danificando forros, instalações e conteúdo da edificação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Madeira/metálica com tratamento e fixações"; (ii) corrigir fixações/recobrimentos conforme manual do fabricante e verificar estanqueidade após chuva ou teste de aspersão; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-07', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Telhas com fixação e recobrimento corretos" (item 2 do checklist ED-07 – Cobertura e Telhados). Critério de aceitação aplicável: Longitudinal/transversal conforme fabricante. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de cobertura e o manual do fabricante das telhas estabelecem os requisitos: estrutura e fixações conforme projeto, recobrimentos e inclinação mínimos, rufos/calhas dimensionados e fixados, e estanqueidade verificada. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de cobertura; manual do fabricante das telhas; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Longitudinal/transversal conforme fabricante" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Coberturas com recobrimento ou fixação inadequados sofrem destelhamento sob vento e infiltrações generalizadas, danificando forros, instalações e conteúdo da edificação. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Longitudinal/transversal conforme fabricante"; (ii) corrigir fixações/recobrimentos conforme manual do fabricante e verificar estanqueidade após chuva ou teste de aspersão; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{praz