insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-08', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Estrutura e pendurais no espaçamento" (item 1 do checklist ED-08 – Forros, Gesso e Drywall). Critério de aceitação aplicável: Conforme fabricante do sistema. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os manuais dos fabricantes de perfis e placas estabelecem os requisitos de forros, gesso e drywall: modulação e suspensão conforme manual, reforços para cargas, tratamento de juntas e nivelamento dentro das tolerâncias. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manuais dos fabricantes (perfis/placas); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Conforme fabricante do sistema" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Forros mal estruturados apresentam fissuras em juntas e risco de queda de placas; ausência de reforços impede fixação segura de luminárias e equipamentos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Conforme fabricante do sistema"; (ii) reforçar/adequar a estrutura de suspensão e refazer o tratamento de juntas conforme manual do fabricante; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-08', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Nivelamento do forro conferido" (item 2 do checklist ED-08 – Forros, Gesso e Drywall). Critério de aceitação aplicável: Sem desníveis visíveis; cotas do projeto. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os manuais dos fabricantes de perfis e placas estabelecem os requisitos de forros, gesso e drywall: modulação e suspensão conforme manual, reforços para cargas, tratamento de juntas e nivelamento dentro das tolerâncias. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manuais dos fabricantes (perfis/placas); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Sem desníveis visíveis; cotas do projeto" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Forros mal estruturados apresentam fissuras em juntas e risco de queda de placas; ausência de reforços impede fixação segura de luminárias e equipamentos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Sem desníveis visíveis; cotas do projeto"; (ii) reforçar/adequar a estrutura de suspensão e refazer o tratamento de juntas conforme manual do fabricante; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-08', 3, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Tratamento de juntas completo" (item 3 do checklist ED-08 – Forros, Gesso e Drywall). Critério de aceitação aplicável: Fita + massa em demãos conforme sistema. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'Os manuais dos fabricantes de perfis e placas estabelecem os requisitos de forros, gesso e drywall: modulação e suspensão conforme manual, reforços para cargas, tratamento de juntas e nivelamento dentro das tolerâncias. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manuais dos fabricantes (perfis/placas); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Fita + massa em demãos conforme sistema" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Forros mal estruturados apresentam fissuras em juntas e risco de queda de placas; ausência de reforços impede fixação segura de luminárias e equipamentos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Fita + massa em demãos conforme sistema"; (ii) reforçar/adequar a estrutura de suspensão e refazer o tratamento de juntas conforme manual do fabricante; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
