insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-09', 6, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Tinta conforme especificação" (item 6 do checklist ED-09 – Pintura Predial). Critério de aceitação aplicável: Marca/linha/cor e validade do lote. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A especificação/memorial e as recomendações do fabricante das tintas estabelecem preparo de superfície, número de demãos, diluição e condições de aplicação, com uniformidade de cor e acabamento conforme padrão aprovado. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Especificação/memorial; fabricante das tintas; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Marca/linha/cor e validade do lote" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Pintura sem preparo adequado descasca e mancha precocemente, gerando retrabalho em fase de entrega e acionamentos de assistência técnica. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Marca/linha/cor e validade do lote"; (ii) preparar novamente a superfície e reaplicar o sistema de pintura conforme especificação, validando padrão em trecho piloto; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-10', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Projeto de fachada com ART disponível" (item 1 do checklist ED-10 – Fachada e Serviços em Altura). Critério de aceitação aplicável: Revisão vigente na frente. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de fachada com ART e a NBR 13755 estabelecem os requisitos de fachadas e serviços em altura: sistema de revestimento conforme projeto (fixações, telas, juntas), ensaios de arrancamento quando exigidos e equipamentos de acesso (balancins/andaimes) conforme NR-18/NR-35. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de fachada com ART; NBR 13755; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Revisão vigente na frente" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desplacamento de fachada é risco grave a terceiros com responsabilização civil e criminal; falhas em equipamentos de acesso em fachada estão entre os acidentes mais severos da construção. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Revisão vigente na frente"; (ii) paralisar a frente até adequação do sistema/equipamentos, executar ensaios de verificação e obter liberação do responsável técnico da fachada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-10', 2, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Balancins/andaime fachadeiro conformes" (item 2 do checklist ED-10 – Fachada e Serviços em Altura). Critério de aceitação aplicável: Projeto, ancoragens e inspeções (interface ST-06/ST-08). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de fachada com ART e a NBR 13755 estabelecem os requisitos de fachadas e serviços em altura: sistema de revestimento conforme projeto (fixações, telas, juntas), ensaios de arrancamento quando exigidos e equipamentos de acesso (balancins/andaimes) conforme NR-18/NR-35. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de fachada com ART; NBR 13755; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Projeto, ancoragens e inspeções (interface ST-06/ST-08)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desplacamento de fachada é risco grave a terceiros com responsabilização civil e criminal; falhas em equipamentos de acesso em fachada estão entre os acidentes mais severos da construção. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Projeto, ancoragens e inspeções (interface ST-06/ST-08)"; (ii) paralisar a frente até adequação do sistema/equipamentos, executar ensaios de verificação e obter liberação do responsável técnico da fachada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-10', 3, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Aderência do revestimento garantida" (item 3 do checklist ED-10 – Fachada e Serviços em Altura). Critério de aceitação aplicável: Telas/pontes de aderência onde exigido; ensaios NBR 13528. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O projeto de fachada com ART e a NBR 13755 estabelecem os requisitos de fachadas e serviços em altura: sistema de revestimento conforme projeto (fixações, telas, juntas), ensaios de arrancamento quando exigidos e equipamentos de acesso (balancins/andaimes) conforme NR-18/NR-35. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Projeto de fachada com ART; NBR 13755; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Telas/pontes de aderência onde exigido; ensaios NBR 13528" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desplacamento de fachada é risco grave a terceiros com responsabilização civil e criminal; falhas em equipamentos de acesso em fachada estão entre os acidentes mais severos da construção. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Telas/pontes de aderência onde exigido; ensaios NBR 13528"; (ii) paralisar a frente até adequação do sistema/equipamentos, executar ensaios de verificação e obter liberação do responsável técnico da fachada; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
