insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-11', 4, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Montagem por empresa habilitada" (item 4 do checklist ED-11 – Elevadores e Transporte Vertical). Critério de aceitação aplicável: Equipe credenciada pelo fabricante; ART de instalação. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante e as normas aplicáveis estabelecem os requisitos de elevadores e transporte vertical: poço e casa de máquinas conforme projeto civil de interface, montagem e ajustes pelo fabricante, testes de segurança e liberação formal. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante; normas aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Equipe credenciada pelo fabricante; ART de instalação" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Interfaces civis fora de tolerância atrasam a montagem do elevador (caminho crítico de entrega) e ajustes inadequados comprometem dispositivos de segurança do equipamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Equipe credenciada pelo fabricante; ART de instalação"; (ii) corrigir as interfaces civis conforme desenho do fabricante e condicionar a liberação aos testes de segurança documentados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-11', 5, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Testes de segurança realizados" (item 5 do checklist ED-11 – Elevadores e Transporte Vertical). Critério de aceitação aplicável: Freios, fim de curso e nivelamento de parada. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante e as normas aplicáveis estabelecem os requisitos de elevadores e transporte vertical: poço e casa de máquinas conforme projeto civil de interface, montagem e ajustes pelo fabricante, testes de segurança e liberação formal. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante; normas aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Freios, fim de curso e nivelamento de parada" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Interfaces civis fora de tolerância atrasam a montagem do elevador (caminho crítico de entrega) e ajustes inadequados comprometem dispositivos de segurança do equipamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Freios, fim de curso e nivelamento de parada"; (ii) corrigir as interfaces civis conforme desenho do fabricante e condicionar a liberação aos testes de segurança documentados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-11', 6, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Documentação de liberação completa" (item 6 do checklist ED-11 – Elevadores e Transporte Vertical). Critério de aceitação aplicável: Relatórios de teste e liberação para uso. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'O manual do fabricante e as normas aplicáveis estabelecem os requisitos de elevadores e transporte vertical: poço e casa de máquinas conforme projeto civil de interface, montagem e ajustes pelo fabricante, testes de segurança e liberação formal. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: Manual do fabricante; normas aplicáveis; Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Relatórios de teste e liberação para uso" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Interfaces civis fora de tolerância atrasam a montagem do elevador (caminho crítico de entrega) e ajustes inadequados comprometem dispositivos de segurança do equipamento. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Relatórios de teste e liberação para uso"; (ii) corrigir as interfaces civis conforme desenho do fabricante e condicionar a liberação aos testes de segurança documentados; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-12', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Projeto de formas e cimbramento disponível" (item 1 do checklist ED-12 – Estrutura Predial — Lajes, Formas e Escoramento). Critério de aceitação aplicável: Dimensionado e com ART. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 14931 (execução) e NBR 15696 (formas e escoramentos) estabelecem os requisitos da estrutura predial: projeto de escoramento atendido, prazos de desforma respeitados conforme resistência, contraflechas e tolerâncias geométricas das lajes. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14931; NBR 15696 (formas/escoramentos); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Dimensionado e com ART" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desforma prematura ou escoramento inadequado pode levar a colapso progressivo — cenário de fatalidades múltiplas — além de deformações permanentes nas lajes. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Dimensionado e com ART"; (ii) manter/recompor o escoramento conforme projeto e condicionar a desforma à comprovação de resistência do concreto (rompimento de CPs); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-12', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Escoramento conforme projeto" (item 2 do checklist ED-12 – Estrutura Predial — Lajes, Formas e Escoramento). Critério de aceitação aplicável: Espaçamento, contraventamento e apoios. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 14931 (execução) e NBR 15696 (formas e escoramentos) estabelecem os requisitos da estrutura predial: projeto de escoramento atendido, prazos de desforma respeitados conforme resistência, contraflechas e tolerâncias geométricas das lajes. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 14931; NBR 15696 (formas/escoramentos); Projeto executivo aprovado (nº/rev. informados na inspeção). O critério "Espaçamento, contraventamento e apoios" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Desforma prematura ou escoramento inadequado pode levar a colapso progressivo — cenário de fatalidades múltiplas — além de deformações permanentes nas lajes. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Espaçamento, contraventamento e apoios"; (ii) manter/recompor o escoramento conforme projeto e condicionar a desforma à comprovação de resistência do concreto (rompimento de CPs); (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
