insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('ED-14', 1, 'Maior — elevar a Crítica se comprometer desempenho estrutural/funcional do ativo', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Checklist de vistoria por unidade aplicado" (item 1 do checklist ED-14 – Vistoria de Entrega de Unidades). Critério de aceitação aplicável: Roteiro padronizado (pisos, paredes, esquadrias, instalações). Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'As NBR 15575 (desempenho de edificações) e NBR 14037 (manual de uso, operação e manutenção) e o contrato estabelecem os requisitos de entrega: unidade conforme memorial, sistemas funcionais testados, manual do proprietário e termo de vistoria formalizados. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 15575 (desempenho); NBR 14037 (manual de uso); contrato. O critério "Roteiro padronizado (pisos, paredes, esquadrias, instalações)" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Entrega com pendências não registradas gera passivo de assistência técnica, disputas com adquirentes e danos à reputação do empreendedor. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Roteiro padronizado (pisos, paredes, esquadrias, instalações)"; (ii) registrar todas as pendências em termo de vistoria com prazo de correção e reinspecionar antes da entrega das chaves; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
