insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('RF-01', 1, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Plano de reforma com ART/RRT" (item 1 do checklist RF-01 – Reforma — Planejamento e Demolição). Critério de aceitação aplicável: NBR 16280 atendida; aprovação do condomínio/responsável quando aplicável. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 16280 (reforma em edificações) exige plano de reforma com ART/RRT aprovado pelo responsável legal da edificação, análise de impacto em sistemas e estrutura, e a Resolução CONAMA 307 disciplina a gestão dos resíduos de demolição. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 16280 (reformas); plano de reforma com ART/RRT; CONAMA 307. O critério "NBR 16280 atendida; aprovação do condomínio/responsável quando aplicável" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Reformas sem plano aprovado podem comprometer estrutura e sistemas prediais (casos de colapso documentados), além de responsabilização do síndico/proprietário e embargos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "NBR 16280 atendida; aprovação do condomínio/responsável quando aplicável"; (ii) suspender os serviços até aprovação formal do plano de reforma com ART/RRT e adequação da gestão de resíduos de demolição; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('RF-01', 2, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Vistoria cautelar registrada" (item 2 do checklist RF-01 – Reforma — Planejamento e Demolição). Critério de aceitação aplicável: As-is fotográfico da área e vizinhança antes do início. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 16280 (reforma em edificações) exige plano de reforma com ART/RRT aprovado pelo responsável legal da edificação, análise de impacto em sistemas e estrutura, e a Resolução CONAMA 307 disciplina a gestão dos resíduos de demolição. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 16280 (reformas); plano de reforma com ART/RRT; CONAMA 307. O critério "As-is fotográfico da área e vizinhança antes do início" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Reformas sem plano aprovado podem comprometer estrutura e sistemas prediais (casos de colapso documentados), além de responsabilização do síndico/proprietário e embargos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "As-is fotográfico da área e vizinhança antes do início"; (ii) suspender os serviços até aprovação formal do plano de reforma com ART/RRT e adequação da gestão de resíduos de demolição; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
insert into public.rnc_textos_base (checklist_codigo, item_numero, gravidade_sugerida, texto_requisito_descumprido, texto_fundamentacao_normativa, texto_risco_consequencia, texto_acao_corretiva) values ('RF-01', 3, 'Menor a Maior, conforme impacto em prazo, custo e etapas subsequentes', 'Durante a inspeção realizada em {{local}} — {{ativo}}, em {{data_inspecao}}, constatou-se o não atendimento ao requisito "Interferências identificadas" (item 3 do checklist RF-01 – Reforma — Planejamento e Demolição). Critério de aceitação aplicável: Estrutura, instalações vivas e elementos que não podem ser removidos. Condição evidenciada: {{descricao_nc}} (registro fotográfico: {{evidencia_foto}}).', 'A NBR 16280 (reforma em edificações) exige plano de reforma com ART/RRT aprovado pelo responsável legal da edificação, análise de impacto em sistemas e estrutura, e a Resolução CONAMA 307 disciplina a gestão dos resíduos de demolição. A verificação foi realizada contra o projeto executivo aprovado nº {{projeto_num}}, rev. {{projeto_rev}}. Referência-base aplicável: NBR 16280 (reformas); plano de reforma com ART/RRT; CONAMA 307. O critério "Estrutura, instalações vivas e elementos que não podem ser removidos" integra o plano de inspeção da obra e constitui requisito verificável de aceitação.', 'Reformas sem plano aprovado podem comprometer estrutura e sistemas prediais (casos de colapso documentados), além de responsabilização do síndico/proprietário e embargos. A permanência da condição descrita mantém ativo o cenário de risco/impacto até a efetiva correção. {{risco_complementar}}', 'Recomenda-se: (i) tratar a condição identificada, restabelecendo o atendimento ao critério "Estrutura, instalações vivas e elementos que não podem ser removidos"; (ii) suspender os serviços até aprovação formal do plano de reforma com ART/RRT e adequação da gestão de resíduos de demolição; (iii) evidenciar a correção com registro fotográfico ({{evidencia_foto_correcao}}) e submeter à reinspeção para fechamento desta RNC. Prazo: {{prazo}} dia(s) | Responsável: {{responsavel}}. {{acao_complementar}}')
